/* Entity dictionary: one record per hormone, receptor, enzyme, metabolite, transporter,
 * signaling protein, organ… Shared by every diagram, the info panel, search and the
 * follow-the-molecule explorer. Content is drawn from Kovacs & Ojeda 6e and Molina 5e
 * unless a reference is named. */
(function () {
  const E = (window.EP.data.entities = {});
  function add(id, type, name, o) {
    E[id] = Object.assign({ id, type, name }, o || {});
    if (o && o.name && o.name !== name && !o.short) E[id].short = name; // compact label for diagrams
  }

  // ======================= HORMONES =======================
  add('insulin', 'hormone', 'Insulin', {
    what: 'A 51-amino-acid peptide (A and B chains joined by disulfide bonds) secreted by pancreatic β-cells; the body\'s principal anabolic, fuel-storage hormone.',
    where: 'Made in β-cells as preproinsulin → proinsulin → insulin + C-peptide (equimolar). Released into the portal vein; the liver removes >50% on first pass (Molina Ch7). Plasma t½ 3–8 min.',
    act: 'Glucose (via glucokinase → ATP → K-ATP closure), amino acids (arginine, leucine), incretins GLP-1 and GIP, vagal (muscarinic) input.',
    inh: 'Somatostatin, α2-adrenergic stimulation (epinephrine/norepinephrine), low glucose.',
    down: 'Insulin receptor → IRS → PI3K → Akt: GLUT4 translocation (muscle, fat), glycogen synthesis (GSK3 inhibition), FOXO1 exclusion (↓ gluconeogenic genes), SREBP-1c (lipogenesis), mTORC1 (protein synthesis), PDE3B (↓ cAMP → ↓ lipolysis).',
    clin: 'Type 1 diabetes: absolute deficiency → hyperglycemia, unrestrained lipolysis and ketogenesis (DKA). Type 2: insulin resistance plus β-cell failure. Insulinoma: hypoglycemia with inappropriately high insulin and C-peptide.',
    tags: ['anabolic', 'beta cell', 'diabetes', 'GLUT4', 'fed state'], refs: ['molina7', 'petersen2018', 'kovacs15'],
  });
  add('glucagon', 'hormone', 'Glucagon', {
    what: 'A 29-amino-acid peptide from pancreatic α-cells (proglucagon processed by PC2). The main counter-regulatory hormone acting on the liver.',
    where: 'Secreted into the portal vein, so the liver sees the highest concentrations. Plasma t½ 5–10 min, degraded mainly by liver (Molina Ch7).',
    act: 'Hypoglycemia, amino acids (especially alanine/arginine), epinephrine (β-adrenergic), sympathetic and vagal input, exercise.',
    inh: 'Glucose, insulin and zinc from neighbouring β-cells (paracrine), somatostatin, GLP-1.',
    down: 'Glucagon receptor (Gs) → adenylyl cyclase → cAMP → PKA: ↑ glycogenolysis, ↑ gluconeogenesis (PEPCK/G6Pase transcription via CREB/CRTC2/PGC-1α; ↓ F-2,6-BP), ↓ glycolysis (L-PK phosphorylation), ↓ malonyl-CoA → ↑ fatty acid oxidation/ketogenesis, ↑ hepatic amino-acid uptake and ureagenesis.',
    clin: 'Glucagonoma: hyperglycemia, weight loss, amino-acid depletion, necrolytic migratory erythema. Relative glucagon excess contributes to hyperglycemia in diabetes. Glucagon injection is rescue therapy for severe hypoglycemia (requires liver glycogen).',
    tags: ['counter-regulatory', 'alpha cell', 'liver', 'cAMP', 'fasting', 'ketogenesis'], refs: ['molina7', 'jiang2003', 'ramnanan2011', 'muller2017', 'albrechtsen2019'],
  });
  add('somatostatin', 'hormone', 'Somatostatin', {
    what: 'Peptide (SST-14/SST-28) made by hypothalamic neurons, pancreatic δ-cells and gut D-cells; a broad inhibitor of secretion.',
    where: 'Hypothalamic periventricular nucleus → portal blood (inhibits GH and TSH); islet δ-cells (paracrine).',
    act: 'GH and IGF-1 (hypothalamic feedback), glucose and nutrients in islets.',
    down: 'SSTR (Gi) → ↓ cAMP, ↑ K⁺ efflux, ↓ Ca²⁺ entry → ↓ secretion of GH, TSH, insulin, glucagon, gastrin.',
    clin: 'Octreotide/lanreotide (analogs) treat acromegaly and neuroendocrine tumors.', tags: ['GH axis', 'islet', 'Gi'], refs: ['kovacs5', 'molina3'],
  });
  add('glp1', 'hormone', 'GLP-1', { name: 'GLP-1 (glucagon-like peptide-1)',
    what: 'Incretin hormone from intestinal L-cells (proglucagon processed by PC1/3).',
    act: 'Luminal nutrients (glucose, fat, protein).', inh: 'Rapid inactivation by DPP-4 (minutes).',
    down: 'GLP-1R (Gs) on β-cells → cAMP → PKA/Epac2 → amplifies glucose-stimulated insulin secretion (glucose-dependent); suppresses glucagon, slows gastric emptying, increases satiety.',
    clin: 'GLP-1 receptor agonists and DPP-4 inhibitors treat type 2 diabetes/obesity; glucose dependence explains low intrinsic hypoglycemia risk.', tags: ['incretin', 'feed-forward'], refs: ['drucker2018', 'molina7'] });
  add('gip', 'hormone', 'GIP', { name: 'GIP (glucose-dependent insulinotropic polypeptide)', what: 'Incretin from duodenal K-cells.', act: 'Luminal glucose and fat.', down: 'GIPR (Gs) on β-cells → cAMP → potentiation of insulin secretion.', tags: ['incretin'], refs: ['molina7'] });
  add('epinephrine', 'hormone', 'Epinephrine', {
    what: 'Catecholamine made mainly by adrenal medullary chromaffin cells (PNMT requires high local cortisol from the adrenal cortex). Plasma t½ <2 min.',
    act: 'Sympathetic preganglionic (cholinergic, nicotinic) firing: stress, hypoglycemia, exercise, hypotension.',
    down: 'β2 (Gs): muscle glycogenolysis, hepatic glucose output; β1/β3: lipolysis; α2 (Gi): ↓ insulin secretion; α1 (Gq): hepatic glycogenolysis, vasoconstriction.',
    clin: 'Pheochromocytoma: paroxysmal hypertension, headache, sweating, hyperglycemia; measure metanephrines.', tags: ['catecholamine', 'stress', 'counter-regulatory', 'adrenal medulla'], refs: ['molina6', 'kovacs13'] });
  add('norepinephrine', 'hormone', 'Norepinephrine', { what: 'Catecholamine released mostly from sympathetic nerve terminals; also from adrenal medulla.', down: 'α1, α2, β1 receptors.', tags: ['catecholamine'], refs: ['molina6'] });
  add('dopamine', 'hormone', 'Dopamine', { what: 'Catecholamine. Released by tuberoinfundibular neurons into the hypophyseal portal blood, it is the dominant **inhibitor** of prolactin secretion.', down: 'D2 receptor (Gi) on lactotrophs → ↓ cAMP, ↓ Ca²⁺ → ↓ prolactin synthesis and release.', act: 'Prolactin itself (short-loop feedback on TIDA neurons).', inh: 'Suckling, stress, estrogen (indirectly).', clin: 'Dopamine antagonists (antipsychotics, metoclopramide) and pituitary stalk compression cause hyperprolactinemia; dopamine agonists (cabergoline) shrink prolactinomas.', tags: ['prolactin', 'TIDA', 'D2'], refs: ['freeman2000', 'kovacs5', 'molina3'] });
  add('cortisol', 'hormone', 'Cortisol', {
    what: 'The major human glucocorticoid (C21 steroid) made in the zona fasciculata. ~90% bound to CBG (transcortin) and albumin. Plasma t½ 70–90 min (Kovacs Ch13).',
    where: 'Adrenal cortex zona fasciculata (and some reticularis); secretion driven by ACTH with a circadian peak around waking.',
    act: 'ACTH (MC2R → cAMP → StAR and steroidogenic enzymes), stress via CRH/AVP, circadian SCN drive.',
    inh: 'Negative feedback on itself via hypothalamic CRH and pituitary ACTH.',
    down: 'Glucocorticoid receptor (cytosolic, chaperone-bound) → nuclear translocation → GRE transcription: ↑ hepatic gluconeogenic enzymes (PEPCK, G6Pase), ↑ muscle proteolysis (substrate supply), permissive for lipolysis, ↓ peripheral insulin sensitivity, anti-inflammatory/immunosuppressive effects, PNMT induction in medulla.',
    clin: 'Cushing syndrome (excess): central obesity, proximal myopathy, striae, hyperglycemia, hypertension. Adrenal insufficiency: hypoglycemia, hypotension, weakness. 11β-HSD2 protects the mineralocorticoid receptor from cortisol in the kidney.',
    tags: ['glucocorticoid', 'HPA', 'stress', 'circadian', 'steroid', 'nuclear receptor'], refs: ['kovacs13', 'molina6', 'oster2017'] });
  add('aldosterone', 'hormone', 'Aldosterone', { what: 'Principal mineralocorticoid, made only in zona glomerulosa (CYP11B2). Minimal protein binding; t½ ≈15–20 min (Molina Ch6).', act: 'Angiotensin II (AT1, Gq), hyperkalemia (depolarization → Ca²⁺), ACTH (minor/acute).', inh: 'Low K⁺, ANP, volume expansion (↓ renin).', down: 'Mineralocorticoid receptor in principal cells → ↑ ENaC, ↑ Na⁺/K⁺-ATPase, ↑ ROMK: Na⁺ retention, K⁺ and H⁺ secretion.', clin: 'Primary aldosteronism: hypertension, hypokalemia, ↓ renin. Primary adrenal insufficiency: aldosterone deficiency → hyponatremia, hyperkalemia, ↑ renin.', tags: ['mineralocorticoid', 'RAAS', 'zona glomerulosa'], refs: ['molina6', 'kovacs13'] });
  add('acth', 'hormone', 'ACTH', { name: 'ACTH (corticotropin)', what: '39-amino-acid peptide cleaved from POMC in pituitary corticotrophs (POMC also yields α-MSH, β-endorphin).', act: 'CRH (CRHR1, Gs) potentiated by AVP (V1b, Gq); circadian drive; stress.', inh: 'Cortisol (long-loop, direct on corticotroph and via CRH).', down: 'MC2R (with MRAP) in adrenal cortex → cAMP → acute StAR-mediated cholesterol delivery; chronic adrenal growth and enzyme expression.', clin: 'High ACTH + POMC-derived MSH activity causes hyperpigmentation in primary adrenal insufficiency. ACTH-secreting adenoma = Cushing disease.', tags: ['HPA', 'POMC', 'corticotroph'], refs: ['kovacs5', 'kovacs13', 'molina3'] });
  add('crh', 'hormone', 'CRH', { name: 'CRH (corticotropin-releasing hormone)', what: '41-aa hypothalamic peptide from parvocellular PVN neurons, released into the hypophyseal portal circulation.', act: 'Stress, circadian input from the SCN, hypoglycemia, inflammatory cytokines.', inh: 'Cortisol (long loop), ACTH (short loop).', down: 'CRHR1 (Gs) on corticotrophs → ACTH release and POMC transcription.', tags: ['HPA', 'hypothalamus'], refs: ['kovacs5'] });
  add('trh', 'hormone', 'TRH', { what: 'Tripeptide (pGlu-His-Pro-NH2) from PVN neurons.', down: 'TRH receptor (Gq) on thyrotrophs → TSH; also stimulates lactotrophs (prolactin).', inh: 'T3 (generated locally from T4 by D2 in hypothalamus).', clin: 'High TRH in primary hypothyroidism can raise prolactin.', tags: ['HPT'], refs: ['kovacs5', 'kovacs12'] });
  add('tsh', 'hormone', 'TSH', { name: 'TSH (thyrotropin)', what: 'Glycoprotein (α subunit shared with LH/FSH/hCG + specific β) from thyrotrophs.', act: 'TRH.', inh: 'T3 inside thyrotrophs (from T4 via D2); somatostatin; dopamine; glucocorticoids.', down: 'TSH receptor (Gs, also Gq) on thyrocytes: ↑ NIS, Tg, TPO expression, iodide organification, Tg endocytosis, hormone release, and follicular cell growth.', clin: 'Most sensitive screening test for primary thyroid disease: ↑ in primary hypothyroidism, ↓ in primary hyperthyroidism. In central (secondary) hypothyroidism TSH is low or inappropriately normal.', tags: ['HPT', 'thyrotroph'], refs: ['kovacs5', 'kovacs12', 'molina4'] });
  add('t4', 'hormone', 'Thyroxine (T4)', { short: 'T4', what: 'Tetra-iodothyronine, the main secretory product of the thyroid; largely a prohormone. ~99.97% protein bound (TBG, transthyretin, albumin). t½ ≈7 days (Kovacs Ch12).', down: 'Converted to active T3 by D1/D2, or inactivated to reverse T3 by D3.', clin: 'Levothyroxine replacement; TBG changes (pregnancy, estrogen) alter total but not free T4.', tags: ['thyroid', 'HPT', 'deiodinase'], refs: ['kovacs12', 'bianco2002'] });
  add('t3', 'hormone', 'Triiodothyronine (T3)', { short: 'T3', what: 'The active thyroid hormone; ~80% is produced outside the thyroid by deiodination of T4. t½ <1 day.', down: 'Thyroid hormone receptor (TRα/TRβ) heterodimerized with RXR on TREs: ↑ Na⁺/K⁺-ATPase, ↑ basal metabolic rate and thermogenesis, ↑ cardiac β1 receptors and α-MHC, ↑ hepatic LDL receptors, required for brain development.', inh: 'D3 inactivation to T2.', tags: ['thyroid', 'nuclear receptor', 'metabolic rate'], refs: ['kovacs12', 'brent2012'] });
  add('rt3', 'metabolite', 'Reverse T3 (rT3)', { short: 'rT3', what: 'Inactive isomer produced by inner-ring (5-) deiodination of T4 by D3 (and D1).', clin: 'Rises in non-thyroidal illness ("euthyroid sick").', tags: ['thyroid'], refs: ['bianco2002'] });
  add('gnrh', 'hormone', 'GnRH', { what: 'Decapeptide secreted in pulses from hypothalamic neurons (arcuate/preoptic) driven by the kisspeptin–neurokinin B–dynorphin pulse generator.', down: 'GnRH receptor (Gq) on gonadotrophs → LH and FSH. **Pulsatility is required** — continuous exposure desensitizes the receptor.', inh: 'Sex steroids (mostly via kisspeptin neurons), prolactin, stress/CRH, energy deficiency (low leptin).', clin: 'Continuous GnRH agonists paradoxically suppress LH/FSH (prostate cancer, precocious puberty). Kallmann syndrome: GnRH-neuron migration failure + anosmia.', tags: ['HPG', 'pulsatile', 'kisspeptin'], refs: ['kovacs5', 'kovacs8', 'kovacs9'] });
  add('lh', 'hormone', 'LH', { name: 'LH (luteinizing hormone)', what: 'Gonadotropin (glycoprotein α + LHβ); t½ ≈30 min (Molina).', act: 'GnRH pulses (fast frequency favours LH); estradiol positive feedback at mid-cycle.', inh: 'Testosterone, progesterone, estradiol (most of the cycle).', down: 'LH receptor (Gs) on Leydig cells (testosterone) and theca cells (androgens); triggers ovulation and luteinization.', tags: ['HPG', 'gonadotropin', 'Leydig', 'theca'], refs: ['molina8', 'molina9', 'kovacs8', 'kovacs9'] });
  add('fsh', 'hormone', 'FSH', { name: 'FSH (follicle-stimulating hormone)', what: 'Gonadotropin (α + FSHβ); t½ 1–3 h (Molina).', act: 'GnRH (slower pulse frequency favours FSH), activin.', inh: 'Inhibin B (selective), estradiol.', down: 'FSH receptor (Gs) on Sertoli cells (ABP, inhibin B, support of spermatogenesis) and granulosa cells (aromatase, follicle growth, LH receptor induction).', tags: ['HPG', 'gonadotropin', 'Sertoli', 'granulosa'], refs: ['molina8', 'molina9'] });
  add('testosterone', 'hormone', 'Testosterone', { what: 'C19 androgen; ~95% from Leydig cells in men. Mostly bound to SHBG and albumin.', act: 'LH → cAMP → StAR/CYP11A1/CYP17A1/HSD17B3.', inh: 'Exogenous androgens via suppression of LH.', down: 'Androgen receptor directly (muscle, bone, spermatogenesis, Wolffian ducts, LH feedback); converted to DHT by 5α-reductase or to estradiol by aromatase.', clin: 'Exogenous testosterone suppresses LH/FSH → low intratesticular testosterone → impaired spermatogenesis and testicular atrophy.', tags: ['androgen', 'HPG', 'Leydig', 'steroid'], refs: ['kovacs9', 'molina8'] });
  add('dht', 'hormone', 'Dihydrotestosterone (DHT)', { short: 'DHT', what: 'Potent androgen formed from testosterone by 5α-reductase (type 2 in genital skin/prostate; type 1 in skin/liver). Binds AR with higher affinity and slower dissociation than testosterone.', down: 'Androgen receptor: external genitalia and prostate development, male-pattern hair, sebaceous glands, prostate growth.', clin: '5α-reductase type 2 deficiency: 46,XY with undervirilized external genitalia but normal Wolffian structures. Finasteride treats BPH.', tags: ['androgen', '5-alpha reductase'], refs: ['kovacs9', 'miller2011'] });
  add('estradiol', 'hormone', 'Estradiol (E2)', { short: 'Estradiol', what: 'Main premenopausal estrogen; made by aromatization of testosterone (granulosa cells, adipose, brain, bone).', down: 'Estrogen receptors ERα/ERβ (nuclear): endometrial proliferation, bone (↓ RANKL), epiphyseal closure in both sexes, LH surge via positive feedback when high and sustained.', clin: 'Aromatase deficiency or ER loss in men → tall stature with unfused epiphyses and osteoporosis.', tags: ['estrogen', 'aromatase', 'HPG'], refs: ['kovacs8', 'molina9'] });
  add('progesterone', 'hormone', 'Progesterone', { what: 'C21 steroid from corpus luteum (luteal phase) and placenta.', down: 'PR: secretory endometrium, thermogenic, slows GnRH pulse frequency; maintains pregnancy.', tags: ['HPG', 'corpus luteum', 'pregnancy'], refs: ['kovacs8', 'kovacs10'] });
  add('inhibin', 'hormone', 'Inhibin B', { short: 'Inhibin', what: 'TGF-β family dimer from Sertoli and granulosa cells.', down: 'Selectively suppresses FSH (not LH) at the gonadotroph.', clin: 'Low inhibin B → ↑ FSH (marker of Sertoli/ovarian reserve failure).', tags: ['HPG', 'Sertoli', 'granulosa'], refs: ['kovacs9', 'molina8'] });
  add('gh', 'hormone', 'Growth hormone (GH)', { short: 'GH', what: '191-aa peptide from somatotrophs, secreted in pulses (largest after sleep onset).', act: 'GHRH, ghrelin, hypoglycemia, fasting, exercise, sleep, amino acids.', inh: 'Somatostatin, IGF-1 (feedback), hyperglycemia, free fatty acids, obesity.', down: 'GH receptor dimer → JAK2 → STAT5: hepatic IGF-1 and IGFBP-3/ALS. Direct metabolic actions: ↑ lipolysis, ↓ insulin sensitivity (diabetogenic), ↑ protein synthesis.', clin: 'Acromegaly (adult excess), gigantism (before epiphyseal fusion); GH deficiency → short stature, ↑ adiposity. Laron syndrome: GH receptor defect → high GH, low IGF-1.', tags: ['GH axis', 'JAK-STAT', 'IGF-1', 'counter-regulatory'], refs: ['kovacs11', 'molina3'] });
  add('ghrh', 'hormone', 'GHRH', { what: 'Hypothalamic (arcuate) releasing hormone.', down: 'GHRH receptor (Gs) on somatotrophs → GH synthesis and release.', inh: 'IGF-1, GH (short loop).', tags: ['GH axis'], refs: ['kovacs5', 'kovacs11'] });
  add('igf1', 'hormone', 'IGF-1', { what: 'Insulin-like growth factor 1, made mainly in liver under GH (JAK2/STAT5) control; circulates bound to IGFBP-3 + ALS (prolongs t½).', down: 'IGF-1 receptor (tyrosine kinase) → growth, chondrocyte proliferation, protein synthesis. Feeds back to inhibit GH (pituitary) and stimulate somatostatin.', clin: 'Best screening test for acromegaly (integrates pulsatile GH).', tags: ['GH axis', 'RTK'], refs: ['kovacs11', 'molina3'] });
  add('ghrelin', 'hormone', 'Ghrelin', { what: 'Acylated peptide from stomach; rises before meals.', down: 'GHS-R → GH release and hunger.', tags: ['GH axis', 'appetite'], refs: ['molina10'] });
  add('prolactin', 'hormone', 'Prolactin', { what: '199-aa peptide from lactotrophs. Unique among anterior pituitary hormones: under **predominantly inhibitory** hypothalamic control (dopamine).', act: 'Loss of dopamine tone (suckling, stress, stalk damage, D2 antagonists), TRH, estrogen.', inh: 'Dopamine (D2, Gi).', down: 'Prolactin receptor (JAK2/STAT5): milk protein synthesis, mammary development; suppresses GnRH (lactational amenorrhea). Short-loop feedback ↑ TIDA dopamine.', clin: 'Hyperprolactinemia → galactorrhea, amenorrhea, ↓ libido; pituitary stalk section ↑ prolactin while other pituitary hormones fall.', tags: ['prolactin', 'dopamine', 'JAK-STAT', 'lactation'], refs: ['freeman2000', 'kovacs5', 'molina3'] });
  add('adh', 'hormone', 'ADH (vasopressin)', { short: 'ADH', what: '9-aa peptide made in supraoptic and paraventricular magnocellular neurons, stored and released from the posterior pituitary.', act: '↑ plasma osmolality (osmoreceptors; very sensitive), ↓ blood volume/pressure (baroreceptors; large changes), angiotensin II, nausea.', inh: 'Low osmolality, ethanol, ANP.', down: 'V2 (Gs) in collecting duct → cAMP → aquaporin-2 insertion → water reabsorption; V1a (Gq) vasoconstriction; V1b corticotroph ACTH release.', clin: 'Central DI (↓ ADH), nephrogenic DI (V2/AQP2 resistance), SIADH (inappropriate ADH → hyponatremia).', tags: ['posterior pituitary', 'water', 'osmolality'], refs: ['kovacs6', 'molina2'] });
  add('oxytocin', 'hormone', 'Oxytocin', { what: '9-aa peptide from PVN/SON magnocellular neurons, released from the posterior pituitary.', act: 'Suckling (milk ejection reflex), cervical stretch (Ferguson reflex) — classic **positive feedback** loops.', down: 'OT receptor (Gq) → myoepithelial contraction (milk ejection), uterine contraction.', tags: ['posterior pituitary', 'positive feedback'], refs: ['molina2', 'kovacs6'] });
  add('pth', 'hormone', 'Parathyroid hormone (PTH)', { short: 'PTH', what: '84-aa peptide from parathyroid chief cells; minute-to-minute regulator of ionized calcium. Serum t½ <5 min (Kovacs Ch14).', act: 'Low ionized Ca²⁺ (via reduced CaSR signaling), high phosphate.', inh: 'Ca²⁺ via CaSR (Gq/Gi), calcitriol (↓ PTH gene transcription), FGF23.', down: 'PTH1R (Gs and Gq). **Direct**: kidney — ↑ Ca²⁺ reabsorption (DCT TRPV5), ↓ phosphate reabsorption (NaPi-IIa/IIc endocytosis), ↑ CYP27B1 (1α-hydroxylase); bone — osteoblast RANKL ↑/OPG ↓ → osteoclast resorption. **Indirect (via calcitriol)**: intestinal Ca²⁺ and phosphate absorption.', clin: 'Primary hyperparathyroidism: ↑ Ca, ↓ phosphate, ↑ PTH. Hypoparathyroidism: ↓ Ca, ↑ phosphate. Intermittent PTH (teriparatide) is anabolic for bone.', tags: ['calcium', 'phosphate', 'bone', 'kidney', 'CaSR'], refs: ['kovacs14', 'molina5', 'blaine2015'] });
  add('calcitriol', 'hormone', '1,25-(OH)₂ vitamin D (calcitriol)', { short: 'Calcitriol', what: 'The active vitamin D hormone, made in the proximal tubule by CYP27B1 (1α-hydroxylase) from 25-OH-D.', act: 'PTH, low phosphate (CYP27B1).', inh: 'FGF23 (↓ CYP27B1, ↑ CYP24A1), calcitriol itself (CYP24A1 induction), high phosphate, high calcium (via ↓ PTH).', down: 'VDR (nuclear receptor, with RXR): intestinal TRPV6/calbindin-D9k/PMCA1b → Ca²⁺ absorption; NaPi-IIb phosphate absorption; ↓ PTH transcription; ↑ FGF23; bone mineralization (indirectly by supplying Ca/P) and RANKL.', clin: 'Deficiency → rickets/osteomalacia with secondary hyperparathyroidism. Granulomatous disease (extra-renal 1α-hydroxylase) → hypercalcemia.', tags: ['vitamin D', 'calcium', 'phosphate', 'nuclear receptor'], refs: ['kovacs14', 'molina5'] });
  add('calcidiol', 'metabolite', '25-OH vitamin D', { what: 'Major circulating storage form (hepatic CYP2R1/CYP27A1 25-hydroxylation); t½ ~15 days (Molina Ch5). Best index of vitamin D status.', tags: ['vitamin D'], refs: ['molina5'] });
  add('fgf23', 'hormone', 'FGF23', { what: 'Phosphaturic hormone secreted by osteocytes/osteoblasts.', act: 'Calcitriol, high phosphate load, PTH.', down: 'FGFR1–α-Klotho in kidney: ↓ NaPi-IIa/IIc (phosphaturia), ↓ CYP27B1 and ↑ CYP24A1 (↓ calcitriol); ↓ PTH secretion.', clin: 'Excess (X-linked hypophosphatemia, tumor-induced osteomalacia) → hypophosphatemia with low/inappropriately normal calcitriol. Rises early in CKD.', tags: ['phosphate', 'bone', 'klotho'], refs: ['martin2012', 'blaine2015'] });
  add('calcitonin', 'hormone', 'Calcitonin', { what: '32-aa peptide from thyroid parafollicular C-cells released when Ca²⁺ rises.', down: 'Calcitonin receptor (Gs) on osteoclasts → acute inhibition of resorption. Physiological role in adult humans is minor (no disorder from its absence after thyroidectomy).', clin: 'Tumor marker for medullary thyroid carcinoma.', tags: ['calcium', 'C cell'], refs: ['kovacs14', 'molina5'] });
  add('angii', 'hormone', 'Angiotensin II', { what: 'Octapeptide produced from angiotensin I by ACE (mainly pulmonary endothelium).', down: 'AT1 (Gq): zona glomerulosa aldosterone, vasoconstriction, proximal Na⁺ reabsorption, thirst, ADH release.', clin: 'ACE inhibitors/ARBs lower aldosterone (and can raise K⁺).', tags: ['RAAS', 'aldosterone'], refs: ['molina6'] });
  add('renin', 'enzyme', 'Renin', { what: 'Aspartyl protease from juxtaglomerular cells; rate-limiting for the RAAS (cleaves angiotensinogen → angiotensin I).', act: '↓ renal perfusion pressure, ↓ macula densa NaCl, sympathetic β1.', inh: 'Angiotensin II, volume expansion, aldosterone-induced Na⁺ retention.', clin: 'High renin with low aldosterone → primary adrenal insufficiency; low renin with high aldosterone → primary aldosteronism.', tags: ['RAAS'], refs: ['molina6'] });
  add('leptin', 'hormone', 'Leptin', { what: 'Adipokine made in proportion to fat mass.', down: 'LepR (JAK2/STAT3) in hypothalamus (arcuate POMC↑/AgRP↓): satiety, permissive for GnRH (reproduction) and energy expenditure.', clin: 'Congenital leptin deficiency → hyperphagic obesity, hypogonadotropic hypogonadism. Low leptin in energy deficit contributes to hypothalamic amenorrhea.', tags: ['adipokine', 'appetite', 'adipose-brain'], refs: ['molina10'] });
  add('adiponectin', 'hormone', 'Adiponectin', { what: 'Adipokine whose levels fall with obesity; enhances insulin sensitivity (AMPK, PPARα).', tags: ['adipokine'], refs: ['molina10'] });
  add('hcg', 'hormone', 'hCG', { what: 'Placental glycoprotein (shares α with LH); acts on LH receptor to rescue the corpus luteum in early pregnancy.', tags: ['pregnancy'], refs: ['kovacs10'] });
  add('kisspeptin', 'hormone', 'Kisspeptin', { what: 'Neuropeptide from arcuate (KNDy) and AVPV neurons; the gatekeeper of GnRH pulses and puberty.', down: 'KISS1R (Gq) on GnRH neurons.', clin: 'Loss-of-function KISS1R mutations → absent puberty.', tags: ['HPG', 'puberty'], refs: ['kovacs8'] });
  add('ifn', 'hormone', 'Cytokines (e.g. IL-6)', { short: 'Cytokines', what: 'Inflammatory signaling proteins; many signal via JAK–STAT.', tags: ['JAK-STAT'] });
  add('anp', 'hormone', 'ANP', { what: 'Atrial natriuretic peptide (atrial stretch).', down: 'NPR-A (guanylyl cyclase receptor) → cGMP: natriuresis, ↓ renin and aldosterone.', tags: ['cGMP'], refs: ['molina6'] });

  // ======================= RECEPTORS =======================
  add('ir', 'receptor', 'Insulin receptor', { short: 'Insulin receptor', what: 'Heterotetrameric (α2β2) receptor tyrosine kinase. Insulin binding to α subunits activates the β-subunit kinase → trans-autophosphorylation of tyrosines.', where: 'Plasma membrane of hepatocytes, myocytes, adipocytes (and many others).', act: 'Insulin.', inh: 'Phosphatases (PTP1B), serine phosphorylation of IRS (PKCε/θ from diacylglycerol), receptor downregulation in chronic hyperinsulinemia.', down: 'Docking of IRS-1/2 and Shc → PI3K/Akt (metabolic) and Ras/MAPK (growth).', clin: 'Insulin receptor mutations (Donohue, type A insulin resistance) → extreme hyperinsulinemia. In common T2D, lipid-induced PKCε inhibits IR kinase in liver (Petersen & Shulman).', tags: ['RTK', 'insulin signaling'], refs: ['petersen2018', 'kovacs3'] });
  add('gcgr', 'receptor', 'Glucagon receptor', { short: 'Glucagon receptor', what: 'Class B GPCR coupled to Gs (and Gq).', where: 'Highly expressed in liver; also kidney, β-cells, adipose, heart (Molina Ch7). Skeletal muscle is not a significant target — muscle relies on epinephrine/β2 for cAMP-driven glycogenolysis.', act: 'Glucagon.', down: 'Gs → adenylyl cyclase → cAMP → PKA; Gq → IP3 → Ca²⁺.', clin: 'Glucagon receptor antagonists lower glucose in diabetes but raise amino acids and α-cell mass (liver–α-cell axis).', tags: ['GPCR', 'Gs', 'liver'], refs: ['molina7', 'muller2017', 'albrechtsen2019'] });
  add('b2ar', 'receptor', 'β2-adrenergic receptor', { short: 'β2-AR', what: 'Gs-coupled receptor for epinephrine.', where: 'Skeletal muscle, liver, bronchial/vascular smooth muscle.', down: 'cAMP → PKA → phosphorylase kinase → glycogen phosphorylase (muscle glycogenolysis).', tags: ['GPCR', 'Gs', 'catecholamine'], refs: ['molina6'] });
  add('b3ar', 'receptor', 'β-adrenergic receptors (adipocyte)', { short: 'β1/β3-AR', what: 'Gs-coupled receptors driving lipolysis in fat.', down: 'cAMP → PKA → phosphorylation of HSL and perilipin-1 → ATGL/HSL lipolysis.', tags: ['lipolysis', 'GPCR'], refs: ['zechner2012'] });
  add('a2ar', 'receptor', 'α2-adrenergic receptor', { short: 'α2-AR', what: 'Gi-coupled receptor.', where: 'β-cells, presynaptic nerve terminals, adipocytes.', down: '↓ cAMP; in β-cells inhibits insulin exocytosis (why insulin falls during stress and exercise).', tags: ['Gi'], refs: ['molina7'] });
  add('gr', 'receptor', 'Glucocorticoid receptor (GR)', { short: 'GR', what: 'Nuclear receptor (NR3C1) held in the cytoplasm by HSP90 chaperones until cortisol binds; then dimerizes, enters the nucleus and binds GREs or tethers to other transcription factors (e.g., represses NF-κB/AP-1).', tags: ['nuclear receptor', 'cortisol'], refs: ['kovacs3', 'kovacs13'] });
  add('mr', 'receptor', 'Mineralocorticoid receptor (MR)', { short: 'MR', what: 'Nuclear receptor binding aldosterone and cortisol with equal affinity; in kidney, 11β-HSD2 converts cortisol to cortisone to keep MR aldosterone-selective.', clin: 'Licorice (glycyrrhetinic acid) inhibits 11β-HSD2 → apparent mineralocorticoid excess.', tags: ['nuclear receptor'], refs: ['molina6'] });
  add('tr', 'receptor', 'Thyroid hormone receptor (TR)', { short: 'TR/RXR', what: 'Nuclear receptor (TRα, TRβ) bound to DNA even without hormone; unliganded TR recruits corepressors, T3 binding swaps them for coactivators.', tags: ['nuclear receptor', 'thyroid'], refs: ['brent2012', 'kovacs12'] });
  add('tshr', 'receptor', 'TSH receptor', { short: 'TSH-R', what: 'GPCR on thyrocyte basolateral membrane (Gs > Gq).', clin: 'Graves disease: stimulating antibodies (TSI) activate TSH-R independent of TSH.', tags: ['GPCR', 'thyroid'], refs: ['kovacs12'] });
  add('mc2r', 'receptor', 'MC2R (ACTH receptor)', { short: 'MC2R', what: 'Gs-coupled melanocortin-2 receptor requiring the accessory protein MRAP.', clin: 'Mutations → familial glucocorticoid deficiency.', tags: ['GPCR', 'HPA'], refs: ['kovacs13'] });
  add('casr', 'receptor', 'Calcium-sensing receptor (CaSR)', { short: 'CaSR', what: 'Class C GPCR that senses extracellular ionized Ca²⁺ (Brown 1993).', where: 'Parathyroid chief cells, thick ascending limb, C-cells.', down: 'Gq/Gi: ↓ PTH secretion and gene expression; in TAL ↑ claudin-14 → ↓ paracellular Ca²⁺ reabsorption.', clin: 'Inactivating mutation → familial hypocalciuric hypercalcemia; cinacalcet is a positive allosteric modulator.', tags: ['calcium', 'GPCR'], refs: ['brown1993', 'kovacs14'] });
  add('pth1r', 'receptor', 'PTH1 receptor', { short: 'PTH1R', what: 'Class B GPCR (Gs and Gq) for PTH and PTHrP.', where: 'Osteoblasts/osteocytes, renal proximal and distal tubule.', tags: ['GPCR', 'calcium'], refs: ['kovacs14'] });
  add('vdr', 'receptor', 'Vitamin D receptor (VDR)', { short: 'VDR', what: 'Nuclear receptor (with RXR) for calcitriol.', tags: ['nuclear receptor', 'vitamin D'], refs: ['kovacs14'] });
  add('ar', 'receptor', 'Androgen receptor (AR)', { short: 'AR', what: 'Nuclear receptor for testosterone and DHT.', clin: 'Complete androgen insensitivity: 46,XY, female external phenotype, high testosterone and LH, absent Müllerian structures (AMH intact).', tags: ['androgen', 'nuclear receptor'], refs: ['kovacs9'] });
  add('er', 'receptor', 'Estrogen receptor (ERα/β)', { short: 'ER', what: 'Nuclear receptors for estradiol.', tags: ['estrogen', 'nuclear receptor'], refs: ['kovacs8'] });
  add('ghr', 'receptor', 'GH receptor', { short: 'GHR', what: 'Cytokine-family receptor (preformed dimer) without intrinsic kinase; uses JAK2.', tags: ['JAK-STAT', 'GH axis'], refs: ['kovacs11'] });
  add('lhr', 'receptor', 'LH receptor', { short: 'LH-R', what: 'Gs-coupled GPCR (also binds hCG).', tags: ['GPCR', 'HPG'], refs: ['kovacs9'] });
  add('fshr', 'receptor', 'FSH receptor', { short: 'FSH-R', what: 'Gs-coupled GPCR on Sertoli and granulosa cells.', tags: ['GPCR', 'HPG'], refs: ['kovacs9'] });
  add('glp1r', 'receptor', 'GLP-1 receptor', { short: 'GLP-1R', what: 'Class B GPCR (Gs) on β-cells (and brain, stomach).', tags: ['incretin', 'Gs'], refs: ['drucker2018'] });
  add('gpcr', 'receptor', 'G protein–coupled receptor', { short: 'GPCR', what: 'Seven-transmembrane receptor. Ligand binding promotes GDP→GTP exchange on the Gα subunit of a heterotrimeric G protein.', tags: ['GPCR', 'signaling'], refs: ['kovacs3'] });
  add('rtk', 'receptor', 'Receptor tyrosine kinase', { short: 'RTK', what: 'Receptor with intrinsic tyrosine-kinase domain (insulin, IGF-1 receptors).', tags: ['RTK'], refs: ['kovacs3'] });
  add('cytor', 'receptor', 'Cytokine-type receptor', { short: 'Cytokine receptor', what: 'Receptors for GH, prolactin, leptin, EPO and cytokines; no intrinsic kinase, they recruit JAK kinases.', tags: ['JAK-STAT'], refs: ['kovacs3'] });
  add('nr', 'receptor', 'Nuclear receptor', { what: 'Ligand-activated transcription factors for steroids, thyroid hormone, vitamin D and retinoids.', tags: ['nuclear receptor'], refs: ['kovacs3'] });
  add('v2r', 'receptor', 'V2 receptor', { short: 'V2R', what: 'Gs-coupled ADH receptor on collecting-duct principal cells.', clin: 'X-linked nephrogenic DI.', tags: ['ADH'], refs: ['kovacs6'] });
  add('d2r', 'receptor', 'Dopamine D2 receptor', { short: 'D2R', what: 'Gi-coupled receptor on lactotrophs.', tags: ['prolactin', 'Gi'], refs: ['freeman2000'] });
  add('rank', 'receptor', 'RANK', { what: 'TNF-receptor family member on osteoclast precursors.', act: 'RANKL.', down: 'NF-κB/NFATc1 → osteoclast differentiation, fusion, activation and survival.', tags: ['bone'], refs: ['boyle2003'] });

  // ======================= SIGNALING PROTEINS & MESSENGERS =======================
  add('irs', 'kinase', 'IRS-1/2', { what: 'Insulin receptor substrates: scaffolds whose phospho-tyrosines dock SH2-domain proteins (p85 of PI3K, Grb2).', inh: 'Serine phosphorylation (PKCθ, JNK, IKKβ, S6K1 — negative feedback/insulin resistance).', tags: ['insulin signaling'], refs: ['petersen2018'] });
  add('pi3k', 'kinase', 'PI3K (class IA)', { short: 'PI3K', what: 'Lipid kinase (p85 regulatory + p110 catalytic) recruited to phospho-IRS; phosphorylates PIP2 → PIP3 at the membrane.', inh: 'PTEN (dephosphorylates PIP3).', tags: ['insulin signaling'], refs: ['petersen2018'] });
  add('pip3', 'messenger', 'PIP3', { name: 'PIP3 (PI-3,4,5-P₃)', what: 'Membrane phospholipid second messenger that recruits PH-domain kinases (PDK1, Akt).', tags: ['insulin signaling'], refs: ['petersen2018'] });
  add('pip2', 'metabolite', 'PIP2', { what: 'Phosphatidylinositol-4,5-bisphosphate; substrate for PI3K (→ PIP3) and PLC (→ IP3 + DAG).', tags: ['signaling'] });
  add('pdk1', 'kinase', 'PDK1 / mTORC2', { short: 'PDK1 + mTORC2', what: 'PDK1 phosphorylates Akt Thr308; mTORC2 phosphorylates Ser473 — together fully activating Akt.', tags: ['insulin signaling'], refs: ['petersen2018'] });
  add('akt', 'kinase', 'Akt (PKB)', { short: 'Akt', what: 'Serine/threonine kinase (Akt2 is the metabolic isoform). Central hub of insulin\'s metabolic actions.', act: 'PIP3 + PDK1/mTORC2 phosphorylation.', inh: 'PTEN/SHIP2 (lower PIP3), PP2A, upstream insulin resistance.', down: 'Phosphorylates AS160/TBC1D4 (GLUT4), GSK3 (→ glycogen synthase activation), FOXO1 (nuclear exclusion → ↓ gluconeogenic genes), TSC2 (→ mTORC1), PDE3B (→ ↓ cAMP), and promotes SREBP-1c.', clin: 'AKT2 loss-of-function mutation causes severe insulin resistance and diabetes.', tags: ['insulin signaling', 'hub'], refs: ['petersen2018'] });
  add('as160', 'kinase', 'AS160 / TBC1D4', { short: 'AS160 (TBC1D4)', what: 'Rab GTPase-activating protein (Rab-GAP) that keeps GLUT4 vesicles intracellular by keeping Rab proteins GDP-bound. Akt phosphorylation inhibits its GAP activity, releasing the brake (Sano 2003).', where: 'Muscle and adipocytes; its paralog TBC1D1 is phosphorylated by AMPK during contraction.', act: '(GAP activity) — default "brake on".', inh: 'Akt (insulin) and AMPK (contraction, mainly via TBC1D1).', down: 'Rab8A/Rab10/Rab13-GTP → GLUT4 vesicle movement, docking and fusion.', clin: 'A truncating TBC1D4 variant (common in Greenland Inuit) causes postprandial hyperglycemia from impaired muscle glucose uptake (Petersen & Shulman).', tags: ['GLUT4', 'Rab-GAP', 'insulin signaling', 'exercise'], refs: ['sano2003', 'petersen2018'] });
  add('rab', 'kinase', 'Rab GTPases (Rab8A/10/13)', { short: 'Rab-GTP', what: 'Small GTPases controlling vesicle trafficking; GTP-bound when AS160/TBC1D1 GAP activity is inhibited.', tags: ['GLUT4'], refs: ['petersen2018'] });
  add('gsk3', 'kinase', 'GSK3', { what: 'Glycogen synthase kinase 3 — phosphorylates and inhibits glycogen synthase. Akt phosphorylation inhibits GSK3, so insulin activates glycogen synthase.', tags: ['glycogen', 'insulin signaling'], refs: ['petersen2018'] });
  add('foxo1', 'tf', 'FOXO1', { what: 'Forkhead transcription factor that, with PGC-1α and CREB/CRTC2, drives PEPCK and G6Pase transcription.', act: 'Fasting, low insulin (FOXO1 stays nuclear).', inh: 'Akt phosphorylation → 14-3-3 binding → nuclear exclusion.', down: '↑ PCK1 (PEPCK), G6PC (G6Pase) transcription → hepatic gluconeogenesis.', clin: 'Liver Foxo1 deletion lowers fasting glucose and blunts glucose production in insulin-receptor knockout mice (Matsumoto 2007).', tags: ['gluconeogenesis', 'insulin signaling', 'transcription'], refs: ['matsumoto2007', 'petersen2018'] });
  add('mtorc1', 'kinase', 'mTORC1', { what: 'Nutrient-sensing kinase complex activated by insulin/Akt (via TSC2–Rheb) and by amino acids (leucine via Rag GTPases at the lysosome).', down: 'S6K1 and 4E-BP1 phosphorylation → ↑ protein synthesis; SREBP-1c processing (lipogenesis); ↓ autophagy. S6K1 also serine-phosphorylates IRS-1 (negative feedback).', clin: 'Rapamycin/everolimus inhibit mTORC1.', tags: ['protein synthesis', 'amino acids', 'leucine'], refs: ['saxton2017'] });
  add('srebp1c', 'tf', 'SREBP-1c', { what: 'Lipogenic transcription factor induced by insulin (Akt/mTORC1).', down: '↑ ACC, FAS, SCD1, glucokinase → de novo lipogenesis.', clin: 'Remains insulin-responsive in insulin-resistant liver ("selective" hepatic insulin resistance) — contributes to steatosis.', tags: ['lipogenesis'], refs: ['petersen2018', 'rui2014'] });
  add('chrebp', 'tf', 'ChREBP', { what: 'Carbohydrate-response element binding protein, activated by glucose metabolites; drives L-PK and lipogenic genes.', inh: 'PKA phosphorylation (glucagon).', tags: ['lipogenesis', 'glucose sensing'], refs: ['rui2014'] });
  add('pde3b', 'enzyme', 'PDE3B', { what: 'Phosphodiesterase 3B; Akt phosphorylates and activates it, degrading cAMP.', where: 'Adipocytes (key), hepatocytes, β-cells.', down: '↓ cAMP → ↓ PKA → ↓ phosphorylation of HSL/perilipin → **antilipolysis**.', tags: ['lipolysis', 'cAMP', 'insulin signaling'], refs: ['petersen2018', 'zechner2012'] });
  add('gs', 'kinase', 'Gs protein', { short: 'Gαs', what: 'Stimulatory G protein; GTP-bound αs activates adenylyl cyclase.', clin: 'Cholera toxin locks Gαs on; activating GNAS mutations → McCune–Albright; inactivating → pseudohypoparathyroidism (PTH resistance).', tags: ['GPCR', 'Gs'], refs: ['kovacs3'] });
  add('gi', 'kinase', 'Gi protein', { short: 'Gαi', what: 'Inhibitory G protein; αi inhibits adenylyl cyclase, βγ opens K⁺ channels.', clin: 'Pertussis toxin blocks Gi.', tags: ['GPCR', 'Gi'], refs: ['kovacs3'] });
  add('gq', 'kinase', 'Gq protein', { short: 'Gαq', what: 'G protein activating phospholipase Cβ.', tags: ['GPCR', 'Gq'], refs: ['kovacs3'] });
  add('ac', 'enzyme', 'Adenylyl cyclase', { what: 'Membrane enzyme converting ATP → cAMP.', act: 'Gαs (and forskolin).', inh: 'Gαi.', tags: ['cAMP'], refs: ['kovacs3'] });
  add('camp', 'messenger', 'cAMP', { what: 'Cyclic AMP — second messenger that activates PKA (and Epac).', inh: 'Phosphodiesterases (PDE3B is activated by insulin).', tags: ['second messenger', 'cAMP', 'glucagon'], refs: ['kovacs3'] });
  add('pka', 'kinase', 'Protein kinase A (PKA)', { short: 'PKA', what: 'cAMP-dependent kinase: cAMP binds regulatory subunits, freeing catalytic subunits.', down: 'Liver: phosphorylase kinase, glycogen synthase (inhibits), PFK-2/FBPase-2 (→ ↓ F-2,6-BP), L-pyruvate kinase (inhibits), CREB; adipocyte: HSL, perilipin-1.', tags: ['cAMP', 'glucagon', 'lipolysis'], refs: ['kovacs3', 'molina7'] });
  add('plc', 'enzyme', 'Phospholipase Cβ', { short: 'PLCβ', what: 'Cleaves PIP2 → IP3 + DAG.', act: 'Gαq.', tags: ['Gq'], refs: ['kovacs3'] });
  add('ip3', 'messenger', 'IP3', { what: 'Inositol trisphosphate — opens ER IP3 receptor Ca²⁺ channels.', tags: ['Gq', 'calcium'], refs: ['kovacs3'] });
  add('dag', 'messenger', 'DAG', { name: 'Diacylglycerol (DAG)', what: 'Membrane lipid messenger activating PKC. Excess intracellular DAG in liver/muscle activates PKCε/θ and causes insulin resistance (Petersen & Shulman).', tags: ['Gq', 'insulin resistance'], refs: ['kovacs3', 'petersen2018'] });
  add('ca', 'ion', 'Ca²⁺', { name: 'Calcium (Ca²⁺)', what: 'Universal intracellular messenger and the most tightly regulated extracellular ion (ionized Ca²⁺ ≈ half of total serum Ca; the rest is albumin-bound or complexed).', tags: ['calcium', 'second messenger'], refs: ['kovacs14'] });
  add('pkc', 'kinase', 'PKC', { what: 'Protein kinase C — activated by DAG (+ Ca²⁺ for classical isoforms).', tags: ['Gq'], refs: ['kovacs3'] });
  add('creb', 'tf', 'CREB / CRTC2', { short: 'CREB/CRTC2', what: 'cAMP-responsive transcription factor (with coactivator CRTC2/TORC2) induced by PKA.', down: '↑ PGC-1α, PEPCK, G6Pase → gluconeogenic program; StAR in steroidogenic cells.', tags: ['cAMP', 'gluconeogenesis', 'transcription'], refs: ['rui2014'] });
  add('pgc1a', 'tf', 'PGC-1α', { what: 'Transcriptional coactivator (with FOXO1, HNF4α, GR) for gluconeogenesis, fatty acid oxidation and mitochondrial biogenesis.', tags: ['gluconeogenesis', 'mitochondria'], refs: ['rui2014', 'molina7'] });
  add('jak2', 'kinase', 'JAK2', { what: 'Janus kinase constitutively associated with cytokine-family receptors (GH, prolactin, leptin, EPO). Ligand-induced receptor conformational change brings two JAK2s together → trans-phosphorylation.', tags: ['JAK-STAT'], refs: ['kovacs3', 'kovacs11'] });
  add('stat5', 'tf', 'STAT5', { what: 'Signal transducer and activator of transcription; JAK2 phosphorylates it → dimerizes → nucleus.', down: 'GH: IGF-1, ALS, IGFBP-3 transcription. Prolactin: milk protein genes.', tags: ['JAK-STAT'], refs: ['kovacs11'] });
  add('socs', 'protein', 'SOCS proteins', { what: 'Suppressors of cytokine signaling, induced by STATs — intracellular negative feedback that terminates JAK–STAT signaling.', tags: ['JAK-STAT', 'desensitization'], refs: ['kovacs3'] });
  add('grk', 'kinase', 'GRK / β-arrestin', { short: 'GRK → β-arrestin', what: 'G protein–coupled receptor kinases phosphorylate agonist-occupied GPCRs; β-arrestin binding uncouples the G protein (desensitization) and targets the receptor for internalization (downregulation).', tags: ['desensitization', 'GPCR'], refs: ['kovacs3'] });
  add('hsp90', 'protein', 'HSP90 chaperone', { what: 'Holds unliganded steroid receptors in the cytoplasm in a ligand-receptive conformation.', tags: ['nuclear receptor'], refs: ['kovacs3'] });
  add('hre', 'gene', 'Hormone response element', { short: 'HRE (DNA)', what: 'DNA sequence (GRE, ERE, TRE, VDRE) to which a nuclear receptor dimer binds to regulate transcription.', tags: ['nuclear receptor', 'transcription'], refs: ['kovacs3'] });
  add('mapk', 'kinase', 'Ras → MAPK (ERK)', { short: 'Ras/MAPK', what: 'Growth/mitogenic branch of insulin and IGF-1 signaling (Grb2–SOS–Ras–Raf–MEK–ERK). Largely preserved in insulin resistance.', tags: ['insulin signaling', 'growth'], refs: ['petersen2018'] });
  add('ampk', 'kinase', 'AMPK', { what: 'AMP-activated protein kinase — the cellular energy sensor, activated when AMP/ATP and ADP/ATP rise (Hardie 2012).', act: '↑ AMP:ATP (exercise, hypoxia, energy stress), LKB1; metformin (indirectly), adiponectin.', down: 'Phosphorylates ACC1/2 (↓ malonyl-CoA → ↑ fat oxidation), TBC1D1 (GLUT4 in contracting muscle), inhibits mTORC1 (via TSC2/raptor), ↓ lipogenesis.', tags: ['energy sensor', 'exercise', 'malonyl-CoA', 'GLUT4'], refs: ['hardie2012', 'richter2013'] });
  add('camk', 'kinase', 'Ca²⁺/CaMKII + Rac1', { short: 'Ca²⁺ / CaMK / Rac1', what: 'Contraction-generated signals: sarcoplasmic-reticulum Ca²⁺ release (CaMKII), mechanical stress → Rac1/actin remodeling. Together with AMPK they drive GLUT4 translocation independently of insulin (Sylow 2017).', tags: ['exercise', 'GLUT4', 'contraction'], refs: ['sylow2017', 'richter2013'] });
  add('tbc1d1', 'kinase', 'TBC1D1', { what: 'AS160 paralog enriched in skeletal muscle; phosphorylated by AMPK during contraction (and by Akt), relieving its Rab-GAP brake on GLUT4.', tags: ['exercise', 'GLUT4'], refs: ['richter2013', 'petersen2018'] });
  add('epac2', 'kinase', 'Epac2', { what: 'cAMP-activated exchange factor in β-cells that amplifies insulin granule exocytosis (with PKA).', tags: ['incretin'], refs: ['drucker2018'] });
  add('pkce', 'kinase', 'PKCε (lipid-activated)', { short: 'PKCε', what: 'Novel PKC activated by hepatic diacylglycerol (DAG). Phosphorylates insulin-receptor Thr1160, impairing its kinase — a central mechanism of hepatic insulin resistance (Petersen & Shulman).', tags: ['insulin resistance', 'DAG'], refs: ['petersen2018'] });
  add('pten', 'enzyme', 'PTEN', { what: 'Lipid phosphatase that converts PIP3 back to PIP2, terminating PI3K signaling.', tags: ['insulin signaling'] });
  add('rheb', 'kinase', 'TSC2 / Rheb', { what: 'Akt phosphorylates and inhibits TSC2 → Rheb-GTP accumulates → activates mTORC1.', tags: ['mTOR'], refs: ['saxton2017'] });

  // ======================= TRANSPORTERS / CHANNELS =======================
  add('glut4', 'transporter', 'GLUT4', { what: 'Insulin- and contraction-responsive facilitative glucose transporter. In the basal state it is sequestered in intracellular GLUT4 storage vesicles; signals move it to the plasma membrane (and T-tubules).', where: 'Skeletal muscle, heart, adipocytes.', act: 'Insulin (IR → PI3K → Akt → AS160/TBC1D4 → Rab GTPases) **and** muscle contraction (AMPK → TBC1D1, Ca²⁺/CaMKII, Rac1) — two distinct signaling routes converging on vesicle trafficking.', inh: 'Insulin resistance (impaired Akt signaling); endocytosis returns it to vesicles when the signal ends.', down: 'Glucose enters → phosphorylated by hexokinase II → G6P → glycogen (muscle, dominant fate) or glycolysis; in fat, glycerol-3-P for triglyceride.', clin: 'Reduced insulin-stimulated GLUT4 translocation is a hallmark of muscle insulin resistance, yet contraction-stimulated uptake is largely preserved — why exercise lowers glucose in T2D (Sylow 2017).', tags: ['insulin', 'exercise', 'muscle', 'adipose', 'diabetes', 'glucose uptake'], refs: ['petersen2018', 'richter2013', 'sylow2017'] });
  add('glut2', 'transporter', 'GLUT2', { what: 'High-capacity, low-affinity bidirectional glucose transporter, always on the membrane (not insulin-regulated).', where: 'Hepatocytes, intestinal and renal basolateral membrane; rodent β-cells (human β-cells mainly GLUT1).', tags: ['liver', 'glucose'], refs: ['molina7'] });
  add('glut1', 'transporter', 'GLUT1/3', { what: 'Basal, insulin-independent glucose transporters (blood–brain barrier GLUT1; neuronal GLUT3; human β-cells GLUT1).', tags: ['brain', 'glucose'], refs: ['molina7'] });
  add('katp', 'channel', 'K-ATP channel (Kir6.2/SUR1)', { short: 'K-ATP channel', what: 'ATP-sensitive K⁺ channel setting the β-cell membrane potential. Rising ATP/ADP closes it.', down: 'Closure → depolarization → voltage-gated Ca²⁺ channels open.', clin: 'Sulfonylureas close it (bind SUR1); diazoxide opens it; activating mutations → neonatal diabetes (treatable with sulfonylureas); inactivating → congenital hyperinsulinism.', tags: ['beta cell', 'insulin secretion'], refs: ['rorsman2018', 'molina7'] });
  add('vgcc', 'channel', 'Voltage-gated Ca²⁺ channels', { short: 'VGCC (Ca²⁺)', what: 'L-type (and P/Q) Ca²⁺ channels opened by depolarization; Ca²⁺ triggers granule exocytosis.', tags: ['beta cell'], refs: ['rorsman2018'] });
  add('nis', 'transporter', 'NIS (Na⁺/I⁻ symporter)', { short: 'NIS', what: 'Basolateral symporter that concentrates iodide in thyrocytes using the Na⁺ gradient (2 Na⁺ : 1 I⁻).', act: 'TSH (transcription and membrane targeting).', inh: 'Perchlorate, thiocyanate (competitive); high iodide (Wolff–Chaikoff).', clin: 'Basis of radioiodine uptake scans and ¹³¹I therapy.', tags: ['thyroid', 'iodide'], refs: ['kovacs12', 'molina4'] });
  add('pendrin', 'transporter', 'Pendrin (SLC26A4)', { short: 'Pendrin', what: 'Apical anion exchanger exporting iodide into the colloid.', clin: 'Pendred syndrome: goiter + sensorineural deafness.', tags: ['thyroid', 'iodide'], refs: ['kovacs12'] });
  add('mct8', 'transporter', 'MCT8', { what: 'Monocarboxylate transporter 8 — thyroid hormone transporter (thyroid export, brain uptake).', clin: 'MCT8 deficiency (Allan–Herndon–Dudley): severe neurodevelopmental impairment with high T3.', tags: ['thyroid'], refs: ['brent2012'] });
  add('trpv5', 'channel', 'TRPV5 (distal tubule)', { short: 'TRPV5', what: 'Apical Ca²⁺ channel in DCT/connecting tubule — the regulated step of renal Ca²⁺ reabsorption.', act: 'PTH, calcitriol.', tags: ['calcium', 'kidney'], refs: ['blaine2015'] });
  add('trpv6', 'channel', 'TRPV6 + calbindin', { short: 'TRPV6 / calbindin', what: 'Apical intestinal Ca²⁺ channel; calbindin-D9k ferries Ca²⁺ across the enterocyte; PMCA1b/NCX1 extrude it. All induced by calcitriol.', tags: ['calcium', 'gut', 'vitamin D'], refs: ['kovacs14'] });
  add('napi', 'transporter', 'NaPi-IIa/IIc', { what: 'Proximal tubule Na⁺-phosphate cotransporters that reabsorb filtered phosphate.', inh: 'PTH and FGF23 (endocytosis and degradation).', tags: ['phosphate', 'kidney'], refs: ['blaine2015', 'martin2012'] });
  add('napi2b', 'transporter', 'NaPi-IIb', { what: 'Intestinal Na⁺-phosphate cotransporter, induced by calcitriol.', tags: ['phosphate', 'gut'], refs: ['blaine2015'] });
  add('cd36', 'transporter', 'CD36 / FATPs', { short: 'CD36/FATP', what: 'Fatty-acid uptake proteins in muscle, heart, adipose.', tags: ['fatty acid'] });
  add('cpt1', 'enzyme', 'CPT-1', { name: 'Carnitine palmitoyltransferase-1 (CPT-1)', what: 'Outer mitochondrial membrane enzyme converting long-chain fatty acyl-CoA to acylcarnitine — the gate controlling fatty acid entry into mitochondria for β-oxidation.', act: 'Low malonyl-CoA (fasting, glucagon, AMPK activation).', inh: '**Malonyl-CoA** (product of ACC; high in the fed state) — McGarry 1977.', down: 'Acylcarnitine → CPT-2 → acyl-CoA in matrix → β-oxidation → acetyl-CoA → TCA or ketogenesis.', clin: 'CPT-1A deficiency → hypoketotic hypoglycemia with fasting.', tags: ['fatty acid oxidation', 'malonyl-CoA', 'ketogenesis', 'acetyl-CoA'], refs: ['mcgarry1977', 'mcgarry1980', 'kovacs15'] });
  add('mct1', 'transporter', 'MCT1/2', { what: 'Monocarboxylate transporters moving lactate, pyruvate and ketone bodies across membranes, including the blood–brain barrier (upregulated with prolonged ketosis).', tags: ['ketone', 'lactate'], refs: ['puchalska2017'] });
  add('aqp2', 'channel', 'Aquaporin-2', { short: 'AQP2', what: 'Water channel inserted into the apical membrane of collecting-duct principal cells by V2/cAMP/PKA signaling.', tags: ['ADH', 'water'], refs: ['kovacs6'] });
  add('enac', 'channel', 'ENaC', { what: 'Epithelial Na⁺ channel in collecting duct; induced by aldosterone.', tags: ['aldosterone'], refs: ['molina6'] });
  add('star', 'transporter', 'StAR', { name: 'StAR (steroidogenic acute regulatory protein)', what: 'Moves cholesterol from outer to inner mitochondrial membrane — the acute, rate-limiting step of steroidogenesis, rapidly induced by ACTH/LH (cAMP).', clin: 'StAR mutations → congenital lipoid adrenal hyperplasia (all steroids deficient, lipid-laden cells).', tags: ['steroidogenesis', 'ACTH', 'LH'], refs: ['miller2011', 'kovacs13'] });

  // ======================= ENZYMES =======================
  add('gk', 'enzyme', 'Glucokinase (hexokinase IV)', { short: 'Glucokinase', what: 'High-Km, non-product-inhibited hexokinase — the glucose sensor of β-cells and hepatocytes.', where: 'β-cells (sets glucose threshold for insulin release); liver (regulated by GKRP and insulin-induced transcription).', clin: 'Heterozygous GCK mutations → MODY2 (mild stable fasting hyperglycemia, higher set-point).', tags: ['beta cell', 'liver', 'glucose sensing'], refs: ['molina7', 'rorsman2018'] });
  add('hk2', 'enzyme', 'Hexokinase II', { short: 'Hexokinase II', what: 'Low-Km hexokinase in muscle and fat, inhibited by its product G6P; transcription induced by insulin.', tags: ['muscle', 'glucose'], refs: ['petersen2018'] });
  add('glycsyn', 'enzyme', 'Glycogen synthase', { what: 'Adds UDP-glucose to glycogen chains. Activated by dephosphorylation (insulin: Akt ⊣ GSK3; PP1) and allosterically by G6P; inhibited by PKA/GSK3 phosphorylation.', tags: ['glycogen', 'glycogenesis'], refs: ['petersen2018', 'molina7'] });
  add('gp', 'enzyme', 'Glycogen phosphorylase', { short: 'Phosphorylase', what: 'Releases glucose-1-P from glycogen. Activated by phosphorylase kinase (PKA, Ca²⁺) and, in muscle, by AMP; inhibited in liver by glucose binding (glucose sensor) and insulin (PP1).', tags: ['glycogen', 'glycogenolysis'], refs: ['molina7'] });
  add('phk', 'enzyme', 'Phosphorylase kinase', { what: 'Activated by PKA phosphorylation and by Ca²⁺ (calmodulin subunit) — so contraction and catecholamines activate muscle glycogenolysis.', tags: ['glycogenolysis'], refs: ['molina7'] });
  add('g6pase', 'enzyme', 'Glucose-6-phosphatase', { short: 'G6Pase', what: 'ER enzyme hydrolysing G6P → glucose for export. Present in liver and kidney (and intestine) but **absent from skeletal muscle**, so muscle glycogen cannot supply blood glucose.', act: 'FOXO1/CREB/PGC-1α, glucocorticoids (transcription).', inh: 'Insulin (via FOXO1 exclusion).', clin: 'Deficiency = von Gierke disease (GSD Ia): fasting hypoglycemia, lactic acidosis, hepatomegaly.', tags: ['gluconeogenesis', 'liver', 'glucose output'], refs: ['molina7', 'pilkis1992'] });
  add('pepck', 'enzyme', 'PEPCK', { name: 'PEPCK (phosphoenolpyruvate carboxykinase)', what: 'Converts oxaloacetate → phosphoenolpyruvate; a key transcriptionally regulated gluconeogenic step.', act: 'cAMP/CREB, FOXO1/PGC-1α, glucocorticoids (GRE), thyroid hormone.', inh: 'Insulin (transcriptional repression).', tags: ['gluconeogenesis'], refs: ['pilkis1992', 'molina7'] });
  add('pc', 'enzyme', 'Pyruvate carboxylase', { what: 'Mitochondrial enzyme: pyruvate + CO₂ + ATP → oxaloacetate. Requires **acetyl-CoA as an obligate allosteric activator** (Utter & Keech). The first committed step of gluconeogenesis from pyruvate/lactate/alanine, and the main anaplerotic reaction.', act: 'Acetyl-CoA (from fatty acid oxidation) — links lipolysis to gluconeogenesis.', down: 'Oxaloacetate → PEPCK (gluconeogenesis) or citrate (TCA).', clin: 'Insulin suppresses gluconeogenesis partly indirectly: ↓ adipose lipolysis → ↓ hepatic acetyl-CoA → ↓ PC activity (Perry 2015).', tags: ['gluconeogenesis', 'acetyl-CoA', 'anaplerosis'], refs: ['perry2015', 'petersen2018'] });
  add('pdh', 'enzyme', 'Pyruvate dehydrogenase (PDH)', { short: 'PDH', what: 'Irreversible mitochondrial complex: pyruvate → acetyl-CoA + CO₂ + NADH. Because it is irreversible, acetyl-CoA can never be turned back into pyruvate — the reason fatty acids cannot make net glucose.', act: 'Dephosphorylation by PDP (insulin, Ca²⁺ in exercising muscle); pyruvate; ADP.', inh: 'PDK4 phosphorylation (fasting, high FFA), products acetyl-CoA and NADH.', clin: 'PDH deficiency → lactic acidosis. Thiamine (B1) is a cofactor.', tags: ['acetyl-CoA', 'pyruvate', 'Randle cycle'], refs: ['kovacs15'] });
  add('pfk1', 'enzyme', 'PFK-1', { name: 'Phosphofructokinase-1 (PFK-1)', what: 'Committed step of glycolysis: F6P → F-1,6-BP.', act: 'AMP, fructose-2,6-bisphosphate.', inh: 'ATP, citrate.', tags: ['glycolysis'], refs: ['pilkis1992'] });
  add('f26bp', 'messenger', 'Fructose-2,6-bisphosphate', { short: 'F-2,6-BP', what: 'Allosteric signal made by the bifunctional PFK-2/FBPase-2. Activates PFK-1 and inhibits FBPase-1, so it switches the liver toward glycolysis.', act: 'Insulin/fed state (PFK-2 dephosphorylated).', inh: 'Glucagon → PKA phosphorylates the bifunctional enzyme → kinase off, phosphatase on → F-2,6-BP falls.', tags: ['glycolysis', 'gluconeogenesis', 'glucagon'], refs: ['pilkis1992', 'jiang2003'] });
  add('fbpase', 'enzyme', 'Fructose-1,6-bisphosphatase', { short: 'FBPase-1', what: 'Gluconeogenic counterpart of PFK-1.', inh: 'F-2,6-BP, AMP.', tags: ['gluconeogenesis'], refs: ['pilkis1992'] });
  add('lpk', 'enzyme', 'L-pyruvate kinase', { short: 'Pyruvate kinase (L)', what: 'Final glycolytic step (PEP → pyruvate). The liver isoform is inhibited by PKA phosphorylation (glucagon), preventing futile recycling of PEP during gluconeogenesis.', tags: ['glycolysis', 'glucagon'], refs: ['pilkis1992'] });
  add('acc', 'enzyme', 'Acetyl-CoA carboxylase (ACC)', { short: 'ACC', what: 'Acetyl-CoA → malonyl-CoA (first committed step of fatty acid synthesis). ACC1 (lipogenic, cytosolic) and ACC2 (mitochondrial surface; regulates CPT-1).', act: 'Citrate (polymerization), insulin (dephosphorylation), SREBP-1c/ChREBP (transcription).', inh: 'AMPK and PKA phosphorylation, long-chain acyl-CoA.', tags: ['malonyl-CoA', 'lipogenesis', 'fatty acid synthesis'], refs: ['kovacs15', 'molina7', 'hardie2012'] });
  add('fas', 'enzyme', 'Fatty acid synthase', { what: 'Multifunctional enzyme building palmitate from acetyl-CoA + 7 malonyl-CoA using NADPH (from the pentose phosphate pathway and malic enzyme).', tags: ['lipogenesis'], refs: ['kovacs15'] });
  add('hsl', 'enzyme', 'HSL / ATGL', { name: 'Hormone-sensitive lipase / ATGL', short: 'ATGL + HSL', what: 'Adipocyte lipases: ATGL removes the first fatty acid from triglyceride, HSL the second (diacylglycerol), MGL the last. PKA phosphorylates HSL and perilipin-1 (releasing CGI-58 to activate ATGL).', act: 'Catecholamines (β-AR → cAMP → PKA), GH and cortisol (slower, permissive), natriuretic peptides (cGMP).', inh: 'Insulin (PDE3B → ↓ cAMP) — the most insulin-sensitive process in the body.', tags: ['lipolysis', 'adipose', 'cAMP'], refs: ['zechner2012', 'petersen2018'] });
  add('lpl', 'enzyme', 'Lipoprotein lipase (LPL)', { short: 'LPL', what: 'Capillary-endothelium enzyme hydrolysing triglyceride in chylomicrons and VLDL so tissues can take up fatty acids. Insulin increases adipose LPL (fed: store fat); fasting/exercise increase muscle LPL.', clin: 'LPL or apoC-II deficiency → severe hypertriglyceridemia (chylomicronemia), pancreatitis risk.', tags: ['lipoprotein', 'adipose', 'triglyceride'], refs: ['kovacs15'] });
  add('hmgcs2', 'enzyme', 'HMG-CoA synthase 2', { short: 'HMGCS2', what: 'Mitochondrial rate-controlling enzyme of ketogenesis (acetoacetyl-CoA + acetyl-CoA → HMG-CoA); induced by fasting (PPARα) and repressed by insulin.', tags: ['ketogenesis'], refs: ['puchalska2017'] });
  add('scot', 'enzyme', 'SCOT', { name: 'SCOT (succinyl-CoA:3-oxoacid CoA transferase)', what: 'Activates acetoacetate for oxidation in extrahepatic tissues. **The liver lacks SCOT**, so it exports ketones rather than burning them.', tags: ['ketolysis'], refs: ['puchalska2017'] });
  add('hmgcr', 'enzyme', 'HMG-CoA reductase', { what: 'Rate-limiting enzyme of cholesterol synthesis (HMG-CoA → mevalonate) in the cytosol/ER. Feedback-inhibited by sterols (SREBP-2 pathway); activated by insulin, inhibited by glucagon/AMPK.', clin: 'Target of statins.', tags: ['cholesterol'], refs: ['kovacs15'] });
  add('alt', 'enzyme', 'ALT / AST (transaminases)', { short: 'Transaminases', what: 'Transfer amino groups between amino acids and α-keto acids (e.g., alanine + α-KG ⇌ pyruvate + glutamate). Freely reversible; collect nitrogen onto glutamate.', tags: ['amino acid', 'nitrogen', 'alanine'], refs: ['felig1973'] });
  add('gdh', 'enzyme', 'Glutamate dehydrogenase', { short: 'GDH', what: 'Oxidative deamination of glutamate → α-ketoglutarate + NH₄⁺ in liver mitochondria.', clin: 'Activating GDH mutations → hyperinsulinism–hyperammonemia syndrome (leucine-sensitive).', tags: ['nitrogen', 'urea cycle'] });
  add('cps1', 'enzyme', 'CPS-1', { name: 'Carbamoyl phosphate synthetase I (CPS-1)', what: 'First, rate-limiting urea-cycle enzyme (NH₄⁺ + HCO₃⁻ → carbamoyl-P), requires N-acetylglutamate.', act: 'N-acetylglutamate (made from glutamate + acetyl-CoA when arginine is high); glucagon and glucocorticoids increase urea-cycle enzyme expression.', clin: 'Urea-cycle defects → hyperammonemia.', tags: ['urea cycle', 'nitrogen'] });
  add('cyp11a1', 'enzyme', 'CYP11A1 (side-chain cleavage)', { short: 'CYP11A1 (P450scc)', what: 'Inner mitochondrial enzyme: cholesterol → pregnenolone (20,22-hydroxylation + side-chain cleavage). Present in all steroidogenic cells.', tags: ['steroidogenesis'], refs: ['miller2011'] });
  add('hsd3b2', 'enzyme', '3β-HSD2', { short: '3β-HSD', what: 'Converts Δ5 steroids (pregnenolone, 17-OH-pregnenolone, DHEA) to Δ4 steroids (progesterone, 17-OHP, androstenedione). Low in zona reticularis, so DHEA accumulates there.', clin: '3β-HSD2 deficiency: salt-wasting CAH, ↑ Δ5 steroids, ambiguous genitalia in both sexes.', tags: ['steroidogenesis', 'CAH'], refs: ['miller2011'] });
  add('cyp17', 'enzyme', '17α-hydroxylase / 17,20-lyase (CYP17A1)', { short: 'CYP17A1', what: 'One enzyme with two activities: 17α-hydroxylase (zona fasciculata, needed for cortisol) and 17,20-lyase (zona reticularis and gonads, needed for androgens; enhanced by cytochrome b5). Absent from zona glomerulosa.', clin: 'CYP17A1 deficiency: ↓ cortisol and sex steroids, ↑ ACTH drives DOC/corticosterone → hypertension, hypokalemia; 46,XY undervirilized; absent puberty.', tags: ['steroidogenesis', 'CAH', 'androgen'], refs: ['miller2011', 'kovacs13'] });
  add('cyp21', 'enzyme', '21-hydroxylase (CYP21A2)', { short: '21-hydroxylase', what: 'ER enzyme: progesterone → 11-deoxycorticosterone (DOC) and 17-OHP → 11-deoxycortisol. Needed for both aldosterone and cortisol.', clin: '21-OH deficiency (>90% of CAH; Speiser 2018): ↓ cortisol (± aldosterone), ↑ ACTH, ↑ 17-OHP shunted to adrenal androgens → virilization; classic salt-wasting form → hyponatremia, hyperkalemia, shock in neonates.', tags: ['steroidogenesis', 'CAH', 'cortisol', 'aldosterone'], refs: ['speiser2018', 'miller2011'] });
  add('cyp11b1', 'enzyme', '11β-hydroxylase (CYP11B1)', { short: '11β-hydroxylase', what: 'Mitochondrial enzyme of zona fasciculata: 11-deoxycortisol → cortisol (and DOC → corticosterone). ACTH-regulated.', clin: '11β-OH deficiency: ↓ cortisol, ↑ ACTH, ↑ 11-deoxycortisol and **DOC (a mineralocorticoid) → hypertension, hypokalemia, low renin**, plus virilization.', tags: ['steroidogenesis', 'CAH'], refs: ['miller2011'] });
  add('cyp11b2', 'enzyme', 'Aldosterone synthase (CYP11B2)', { short: 'Aldosterone synthase', what: 'Zona glomerulosa-only enzyme performing 11β-hydroxylation, 18-hydroxylation and 18-oxidation: DOC → corticosterone → 18-OH-corticosterone → aldosterone. Regulated by angiotensin II and K⁺.', clin: 'Deficiency → isolated salt wasting (no virilization, cortisol normal). Glucocorticoid-remediable aldosteronism: CYP11B1/B2 chimeric gene under ACTH control.', tags: ['steroidogenesis', 'aldosterone', 'zona glomerulosa'], refs: ['miller2011'] });
  add('srd5a2', 'enzyme', '5α-reductase (type 2)', { short: '5α-reductase', what: 'Converts testosterone → DHT in genital skin, prostate, hair follicles.', clin: 'Deficiency: 46,XY with ambiguous/female-appearing external genitalia at birth, virilization at puberty; inhibited by finasteride.', tags: ['androgen', 'DHT'], refs: ['kovacs9', 'miller2011'] });
  add('cyp19', 'enzyme', 'Aromatase (CYP19A1)', { short: 'Aromatase', what: 'Converts androgens to estrogens (testosterone → estradiol; androstenedione → estrone). Granulosa cells (FSH-induced), placenta, adipose, brain, bone.', clin: 'Aromatase inhibitors (letrozole) treat ER+ breast cancer. Deficiency → maternal virilization in pregnancy; tall stature/osteoporosis in men.', tags: ['estrogen', 'androgen'], refs: ['kovacs8', 'miller2011'] });
  add('hsd17b3', 'enzyme', '17β-HSD3', { short: '17β-HSD', what: 'Androstenedione → testosterone (testis-specific type 3; type 5/AKR1C3 elsewhere).', tags: ['androgen'], refs: ['miller2011'] });
  add('sult2a1', 'enzyme', 'SULT2A1', { short: 'DHEA sulfotransferase', what: 'Converts DHEA → DHEA-S in zona reticularis (DHEA-S is the most abundant circulating adrenal steroid).', tags: ['androgen', 'zona reticularis'], refs: ['miller2011'] });
  add('hsd11b2', 'enzyme', '11β-HSD2', { what: 'Kidney (and placenta) enzyme inactivating cortisol → cortisone, protecting the MR.', tags: ['cortisol', 'aldosterone'], refs: ['molina6'] });
  add('pnmt', 'enzyme', 'PNMT', { what: 'Phenylethanolamine N-methyltransferase: norepinephrine → epinephrine. Induced by the very high cortisol reaching the medulla through the intra-adrenal portal circulation.', tags: ['catecholamine', 'adrenal medulla'], refs: ['molina6'] });
  add('th', 'enzyme', 'Tyrosine hydroxylase', { what: 'Rate-limiting catecholamine enzyme (tyrosine → L-DOPA); feedback-inhibited by catecholamines, activated by nerve stimulation.', tags: ['catecholamine'], refs: ['molina6'] });
  add('dbh', 'enzyme', 'Dopamine β-hydroxylase', { short: 'DBH', what: 'Inside chromaffin granules: dopamine → norepinephrine.', tags: ['catecholamine'], refs: ['molina6'] });
  add('aadc', 'enzyme', 'Aromatic L-amino acid decarboxylase', { short: 'AADC', what: 'L-DOPA → dopamine (cytosol).', tags: ['catecholamine'], refs: ['molina6'] });
  add('comt', 'enzyme', 'COMT / MAO', { what: 'Catecholamine-degrading enzymes producing metanephrines and VMA.', clin: 'Plasma free metanephrines are the preferred screening test for pheochromocytoma.', tags: ['catecholamine'], refs: ['molina6'] });
  add('tpo', 'enzyme', 'Thyroid peroxidase (TPO)', { short: 'TPO', what: 'Apical enzyme using H₂O₂ (from DUOX2) to oxidize iodide, iodinate tyrosyl residues of thyroglobulin (organification → MIT/DIT) and **couple** iodotyrosines (DIT+DIT → T4; MIT+DIT → T3).', inh: 'Thionamides (methimazole, PTU); excess iodide transiently (Wolff–Chaikoff).', clin: 'Anti-TPO antibodies mark Hashimoto thyroiditis.', tags: ['thyroid', 'organification', 'coupling'], refs: ['kovacs12', 'molina4'] });
  add('duox', 'enzyme', 'DUOX2', { what: 'Dual oxidase generating H₂O₂ at the apical membrane for TPO.', tags: ['thyroid'], refs: ['kovacs12'] });
  add('d1', 'enzyme', 'Deiodinase type 1 (D1)', { short: 'D1', what: 'Liver/kidney/thyroid deiodinase (outer- and inner-ring); contributes plasma T3; clears rT3.', inh: 'PTU (not methimazole).', tags: ['deiodinase', 'thyroid'], refs: ['bianco2002'] });
  add('d2', 'enzyme', 'Deiodinase type 2 (D2)', { short: 'D2', what: 'Outer-ring deiodinase (T4 → T3) in brain, pituitary, brown fat, muscle. Generates the intracellular T3 that mediates negative feedback in thyrotrophs and hypothalamus; contributes substantially to plasma T3 (Bianco 2002).', tags: ['deiodinase', 'thyroid', 'feedback'], refs: ['bianco2002'] });
  add('d3', 'enzyme', 'Deiodinase type 3 (D3)', { short: 'D3', what: 'Inner-ring deiodinase inactivating T4 → rT3 and T3 → T2 (placenta, brain, some tumors).', clin: 'Massive D3 in hemangiomas → "consumptive hypothyroidism".', tags: ['deiodinase'], refs: ['bianco2002'] });
  add('cyp27b1', 'enzyme', '1α-hydroxylase (CYP27B1)', { short: '1α-hydroxylase', what: 'Proximal-tubule mitochondrial enzyme: 25-OH-D → 1,25-(OH)₂D (calcitriol).', act: 'PTH, hypophosphatemia.', inh: 'FGF23, calcitriol, hyperphosphatemia.', clin: 'Falls with loss of renal mass in CKD.', tags: ['vitamin D', 'kidney'], refs: ['kovacs14', 'martin2012'] });
  add('cyp24a1', 'enzyme', '24-hydroxylase (CYP24A1)', { short: 'CYP24A1', what: 'Inactivates 25-OH-D and calcitriol; induced by calcitriol and FGF23.', tags: ['vitamin D'], refs: ['martin2012'] });
  add('rankl', 'protein', 'RANKL', { what: 'TNF-family cytokine on osteoblast-lineage cells/osteocytes; the essential osteoclastogenic signal (Boyle 2003).', act: 'PTH (continuous), calcitriol, glucocorticoids, inflammatory cytokines.', inh: 'Estrogen.', tags: ['bone'], refs: ['boyle2003', 'kovacs14'] });
  add('opg', 'protein', 'Osteoprotegerin (OPG)', { short: 'OPG', what: 'Soluble decoy receptor that binds RANKL and blocks osteoclastogenesis.', act: 'Estrogen.', inh: 'PTH, glucocorticoids.', clin: 'Denosumab is an anti-RANKL antibody that mimics OPG.', tags: ['bone'], refs: ['boyle2003'] });
  add('mcsf', 'protein', 'M-CSF', { what: 'Colony-stimulating factor required (with RANKL) for osteoclast precursor proliferation and survival.', tags: ['bone'], refs: ['boyle2003'] });
  add('sclerostin', 'protein', 'Sclerostin', { what: 'Osteocyte-derived Wnt inhibitor that restrains bone formation; suppressed by mechanical loading and PTH.', clin: 'Romosozumab (anti-sclerostin) is bone-anabolic.', tags: ['bone', 'Wnt'] });

  // ======================= METABOLITES =======================
  add('glucose', 'metabolite', 'Glucose', { what: 'Main circulating carbohydrate fuel. Obligatory fuel for red cells and (except during prolonged ketosis) the brain.', where: 'Plasma level reflects the balance between appearance (gut absorption, hepatic and renal glucose output) and disposal (brain, muscle, fat, liver).', down: 'Glucose → G6P → glycolysis, glycogen, pentose phosphate pathway, or (liver/fat) acetyl-CoA → fatty acids.', tags: ['carbohydrate', 'fuel', 'diabetes'], refs: ['kovacs15', 'molina7'] });
  add('g6p', 'metabolite', 'Glucose-6-phosphate', { short: 'G6P', what: 'The branch-point metabolite of glucose metabolism — traps glucose in the cell.', down: 'Glycolysis (F6P), glycogen (G1P → UDP-glucose), pentose phosphate pathway (G6PD → NADPH), or back to glucose (liver/kidney only, G6Pase).', tags: ['branch point', 'glycogen', 'glycolysis', 'pentose phosphate'], refs: ['kovacs15'] });
  add('g1p', 'metabolite', 'Glucose-1-phosphate / UDP-glucose', { short: 'G1P / UDP-glc', what: 'Glycogen precursor/product (phosphoglucomutase interconverts with G6P).', tags: ['glycogen'] });
  add('glycogen', 'metabolite', 'Glycogen', { what: 'Branched glucose polymer. Liver glycogen buffers blood glucose between meals (exportable via G6Pase) and is largely depleted after the first day or so of fasting (Cahill 2006); muscle glycogen is a local fuel only (no G6Pase).', tags: ['storage', 'glycogenesis', 'glycogenolysis'], refs: ['cahill2006', 'kovacs15'] });
  add('f6p', 'metabolite', 'Fructose-6-P', { short: 'F6P', tags: ['glycolysis'] });
  add('f16bp', 'metabolite', 'Fructose-1,6-bisP', { short: 'F-1,6-BP', tags: ['glycolysis'] });
  add('gap', 'metabolite', 'Triose phosphates (G3P/DHAP)', { short: 'Triose-P', what: 'Glyceraldehyde-3-P and DHAP. DHAP → glycerol-3-phosphate provides the backbone for triglyceride synthesis; glycerol enters gluconeogenesis here.', tags: ['glycolysis', 'glycerol'] });
  add('pep', 'metabolite', 'Phosphoenolpyruvate', { short: 'PEP', tags: ['glycolysis', 'gluconeogenesis'] });
  add('pyruvate', 'metabolite', 'Pyruvate', { what: 'End product of glycolysis — a crossroads: → lactate (LDH), → alanine (ALT), → acetyl-CoA (PDH, irreversible), → oxaloacetate (pyruvate carboxylase, gluconeogenesis/anaplerosis).', tags: ['branch point', 'acetyl-CoA', 'gluconeogenesis'], refs: ['kovacs15'] });
  add('lactate', 'metabolite', 'Lactate', { what: 'Product of glycolysis via LDH (regenerating NAD⁺). Released by red cells, exercising muscle, gut and adipose; taken up by liver (Cori cycle) and kidney for gluconeogenesis, and oxidized by heart and oxidative muscle.', tags: ['Cori cycle', 'gluconeogenesis', 'exercise'], refs: ['kovacs15'] });
  add('alanine', 'metabolite', 'Alanine', { what: 'Major gluconeogenic amino acid released by muscle; carries both carbon (pyruvate skeleton) and nitrogen to the liver (glucose–alanine cycle, Felig 1973).', tags: ['amino acid', 'gluconeogenesis', 'nitrogen'], refs: ['felig1973'] });
  add('glutamine', 'metabolite', 'Glutamine', { what: 'Most abundant plasma amino acid; nitrogen carrier from muscle to gut and kidney; renal glutamine metabolism yields NH₄⁺ (acid excretion) and gluconeogenic carbon, prominent in prolonged fasting.', tags: ['amino acid', 'kidney', 'nitrogen'], refs: ['cahill2006'] });
  add('acetylcoa', 'metabolite', 'Acetyl-CoA', { what: 'The two-carbon hub of fuel metabolism, produced by PDH (from glucose/pyruvate), β-oxidation, ketogenic amino acids and ketolysis.', where: 'Made in mitochondria; exported to cytosol as citrate (ATP-citrate lyase) for fatty acid and cholesterol synthesis.', down: 'TCA cycle (with oxaloacetate → citrate), ketogenesis (liver, when OAA is diverted to gluconeogenesis), fatty acid/cholesterol synthesis (cytosol), allosteric activation of pyruvate carboxylase, inhibition of PDH.', clin: '**No net glucose from acetyl-CoA in humans**: PDH is irreversible and the TCA cycle loses both carbons as CO₂ for each acetyl unit entering, so even-chain fatty acids cannot be net gluconeogenic (glycerol and odd-chain propionyl-CoA can).', tags: ['hub', 'TCA', 'ketogenesis', 'fatty acid oxidation', 'fatty acid synthesis', 'pyruvate dehydrogenase', 'gluconeogenesis'], refs: ['kovacs15', 'perry2015', 'puchalska2017'] });
  add('oaa', 'metabolite', 'Oxaloacetate', { short: 'OAA', what: 'Four-carbon TCA intermediate that condenses with acetyl-CoA to form citrate — **and** the starting point of gluconeogenesis (via PEPCK). During fasting, OAA is pulled into gluconeogenesis and the high NADH/NAD⁺ ratio from β-oxidation favours malate; acetyl-CoA therefore cannot all enter the TCA cycle and is diverted to ketogenesis.', tags: ['TCA', 'gluconeogenesis', 'ketogenesis', 'bottleneck'], refs: ['kovacs15', 'puchalska2017'] });
  add('citrate', 'metabolite', 'Citrate', { what: 'TCA intermediate; when energy is abundant it is exported to the cytosol, cleaved by ATP-citrate lyase to acetyl-CoA, and allosterically activates ACC while inhibiting PFK-1 — a feed-forward signal for fat synthesis.', tags: ['TCA', 'lipogenesis', 'allosteric'], refs: ['kovacs15'] });
  add('akg', 'metabolite', 'α-Ketoglutarate', { short: 'α-KG', tags: ['TCA', 'transamination'] });
  add('succoa', 'metabolite', 'Succinyl-CoA', { tags: ['TCA'] });
  add('malate', 'metabolite', 'Malate', { tags: ['TCA', 'gluconeogenesis'] });
  add('malonylcoa', 'metabolite', 'Malonyl-CoA', { what: 'Product of ACC; the first committed intermediate of fatty acid synthesis **and** the physiological inhibitor of CPT-1 (McGarry 1977). It reciprocally couples synthesis and oxidation so the cell does not make and burn fat at the same time.', act: 'Insulin (ACC dephosphorylation + SREBP-1c), citrate, high-carbohydrate fed state.', inh: 'Glucagon/PKA and AMPK (ACC phosphorylation), long-chain acyl-CoA, malonyl-CoA decarboxylase.', down: '⊣ CPT-1 → ↓ fatty acid entry into mitochondria → ↓ β-oxidation and ketogenesis; → fatty acid synthase → palmitate.', tags: ['fatty acid synthesis', 'fatty acid oxidation', 'CPT-1', 'ketogenesis', 'regulator'], refs: ['mcgarry1977', 'mcgarry1980', 'kovacs15'] });
  add('ffa', 'metabolite', 'Free fatty acids (NEFA)', { short: 'Fatty acids', what: 'Non-esterified fatty acids, carried on albumin; released by adipose lipolysis. Fuel for muscle, heart and liver; substrate for hepatic ketogenesis and re-esterification to VLDL-triglyceride.', tags: ['fatty acid', 'lipolysis', 'fasting'], refs: ['zechner2012', 'kovacs15'] });
  add('facoa', 'metabolite', 'Fatty acyl-CoA', { short: 'Acyl-CoA', tags: ['fatty acid'] });
  add('glycerol', 'metabolite', 'Glycerol', { what: 'Backbone released by lipolysis. Adipocytes lack significant glycerol kinase, so glycerol goes to the liver (and kidney), where glycerol kinase → glycerol-3-P → DHAP → gluconeogenesis. The only net-gluconeogenic part of triglyceride.', tags: ['lipolysis', 'gluconeogenesis'], refs: ['kovacs15'] });
  add('g3p', 'metabolite', 'Glycerol-3-phosphate', { short: 'Glycerol-3-P', what: 'Triglyceride backbone; adipocytes make it from glucose (DHAP) — one reason insulin-stimulated glucose uptake promotes fat storage.', tags: ['triglyceride'] });
  add('tg', 'metabolite', 'Triglyceride', { short: 'Triglyceride (TG)', what: 'Storage lipid (glycerol + 3 fatty acids). Stored in adipocyte lipid droplets; exported from liver in VLDL and from gut in chylomicrons.', tags: ['lipid', 'storage', 'lipoprotein'], refs: ['kovacs15'] });
  add('ketones', 'metabolite', 'Ketone bodies (acetoacetate, β-hydroxybutyrate)', { short: 'Ketone bodies', what: 'Water-soluble fuels made only in liver mitochondria from acetyl-CoA (HMGCS2). The liver cannot oxidize them (no SCOT). In prolonged starvation they become the predominant brain fuel (Owen 1967), sparing glucose and therefore muscle protein.', act: 'High fatty acid delivery + low insulin/high glucagon (low malonyl-CoA → CPT-1 open) + OAA diverted to gluconeogenesis.', inh: 'Insulin (antilipolysis, ↓ HMGCS2), high malonyl-CoA.', clin: 'Diabetic ketoacidosis: absent insulin + glucagon excess → uncontrolled lipolysis and ketogenesis. SGLT2 inhibitors can cause euglycemic DKA.', tags: ['ketogenesis', 'ketolysis', 'fasting', 'brain', 'acetyl-CoA'], refs: ['puchalska2017', 'owen1967', 'cahill2006', 'kovacs15'] });
  add('aa', 'metabolite', 'Amino acids', { what: 'Building blocks of protein and, when in excess or during fasting, fuels: their carbon skeletons are glucogenic (→ pyruvate/TCA intermediates) or ketogenic (→ acetyl-CoA/acetoacetyl-CoA); their nitrogen is disposed of as urea.', act: 'Protein meal; muscle proteolysis (cortisol, low insulin).', down: 'Protein synthesis (mTORC1), transamination, deamination → urea; stimulate both insulin and glucagon secretion (so a protein meal does not cause hypoglycemia).', tags: ['amino acid', 'protein', 'nitrogen', 'urea', 'mTOR'], refs: ['albrechtsen2019', 'saxton2017', 'felig1973'] });
  add('leucine', 'metabolite', 'Leucine', { what: 'Branched-chain, purely ketogenic amino acid and the key nutrient activator of mTORC1 (via Sestrin2/Rag GTPases).', tags: ['amino acid', 'mTOR'], refs: ['saxton2017'] });
  add('nh4', 'ion', 'Ammonia (NH₄⁺)', { short: 'NH₄⁺', what: 'Toxic nitrogen released by deamination; detoxified to urea in the liver (or glutamine).', tags: ['nitrogen', 'urea cycle'] });
  add('urea', 'metabolite', 'Urea', { what: 'Non-toxic nitrogen end product made only in liver; excreted by kidney.', tags: ['urea cycle', 'nitrogen'] });
  add('carbamoylp', 'metabolite', 'Carbamoyl phosphate', { tags: ['urea cycle'] });
  add('ornithine', 'metabolite', 'Ornithine / citrulline / arginine', { short: 'Urea-cycle intermediates', tags: ['urea cycle'] });
  add('vldl', 'metabolite', 'VLDL', { what: 'Liver-derived triglyceride-rich lipoprotein (apoB-100). Exports hepatic triglyceride (from DNL and re-esterified FFA); LPL delivers its fatty acids to muscle and adipose; remnants become IDL → LDL.', tags: ['lipoprotein', 'triglyceride'], refs: ['kovacs15'] });
  add('chylo', 'metabolite', 'Chylomicrons', { what: 'Intestinal triglyceride-rich lipoproteins (apoB-48) carrying dietary fat via lymph; hydrolysed by LPL; remnants cleared by liver.', tags: ['lipoprotein', 'dietary fat'], refs: ['kovacs15'] });
  add('ldl', 'metabolite', 'LDL', { what: 'Cholesterol-rich lipoprotein (apoB-100) cleared by LDL receptors (liver; steroidogenic cells use it as cholesterol source).', clin: 'Familial hypercholesterolemia (LDLR mutation). Hypothyroidism raises LDL (↓ hepatic LDL receptors).', tags: ['lipoprotein', 'cholesterol'], refs: ['kovacs15'] });
  add('hdl', 'metabolite', 'HDL', { what: 'Reverse cholesterol transport from tissues to liver (and to steroidogenic tissues via SR-BI).', tags: ['lipoprotein', 'cholesterol'], refs: ['kovacs15'] });
  add('cholesterol', 'metabolite', 'Cholesterol', { what: 'Membrane sterol and the precursor of all steroid hormones, bile acids and vitamin D. Steroidogenic cells obtain it from LDL/HDL, de novo synthesis (HMG-CoA reductase) and lipid-droplet esters.', tags: ['steroidogenesis', 'lipoprotein', 'HMG-CoA reductase'], refs: ['miller2011', 'kovacs15'] });
  add('mevalonate', 'metabolite', 'Mevalonate', { tags: ['cholesterol'] });
  add('hmgcoa', 'metabolite', 'HMG-CoA', { what: 'Branch point: in the cytosol → mevalonate → cholesterol; in liver mitochondria → acetoacetate (ketogenesis).', tags: ['cholesterol', 'ketogenesis'] });
  add('palmitate', 'metabolite', 'Palmitate (C16:0)', { short: 'Palmitate', tags: ['fatty acid synthesis'] });
  add('nadph', 'metabolite', 'NADPH', { what: 'Reducing equivalents for fatty acid and cholesterol synthesis and glutathione; from the oxidative pentose phosphate pathway (G6PD) and malic enzyme.', tags: ['pentose phosphate', 'lipogenesis'] });
  add('ribose5p', 'metabolite', 'Ribose-5-phosphate', { short: 'Ribose-5-P', what: 'Pentose phosphate pathway product used for nucleotide synthesis.', tags: ['pentose phosphate'] });
  add('nadh', 'metabolite', 'NADH / NAD⁺', { short: 'NADH/NAD⁺', what: 'Redox couple. β-Oxidation raises mitochondrial NADH/NAD⁺, which inhibits PDH and favours OAA → malate (helping divert OAA from the TCA cycle toward gluconeogenesis and acetyl-CoA toward ketones).', tags: ['redox', 'ETC'] });
  add('atp', 'metabolite', 'ATP / AMP', { short: 'ATP:AMP', what: 'Cellular energy charge. ↑ AMP activates AMPK, PFK-1 and (muscle) glycogen phosphorylase; ATP inhibits PFK-1 and citrate synthase/isocitrate DH.', tags: ['energy charge', 'AMPK'], refs: ['hardie2012'] });
  add('o2', 'metabolite', 'O₂ → H₂O', { tags: ['ETC'] });
  add('etc', 'process', 'Electron transport chain + ATP synthase', { short: 'ETC → ATP', what: 'NADH and FADH₂ donate electrons to complexes I–IV; the proton gradient drives ATP synthase (oxidative phosphorylation). Thyroid hormone increases mitochondrial capacity; UCP1 uncouples in brown fat.', tags: ['oxidative phosphorylation', 'mitochondria'], refs: ['kovacs15'] });
  add('tca', 'process', 'TCA cycle', { short: 'TCA cycle', what: 'Mitochondrial cycle oxidizing acetyl-CoA to CO₂, generating NADH/FADH₂/GTP. Its intermediates are also biosynthetic precursors (cataplerosis) and must be replenished (anaplerosis, mainly pyruvate carboxylase).', tags: ['TCA', 'acetyl-CoA', 'oxidation'], refs: ['kovacs15'] });
  add('mitpyr', 'metabolite', 'Pyruvate (mitochondrial)', { short: 'Pyruvate', tags: ['mitochondria'] });
  add('iodide', 'ion', 'Iodide (I⁻)', { short: 'I⁻', what: 'Essential substrate for thyroid hormones, trapped by NIS.', clin: 'Iodine deficiency → goiter and hypothyroidism (the leading cause worldwide).', tags: ['thyroid'], refs: ['kovacs12'] });
  add('tg_thy', 'protein', 'Thyroglobulin (Tg)', { short: 'Thyroglobulin', what: 'Large glycoprotein secreted into the colloid whose tyrosines are iodinated; the storage form of thyroid hormone (weeks of supply).', clin: 'Serum Tg is a tumor marker after thyroidectomy for differentiated cancer.', tags: ['thyroid', 'storage'], refs: ['kovacs12', 'molina4'] });
  add('mitdit', 'metabolite', 'MIT / DIT', { what: 'Mono- and di-iodotyrosine residues on thyroglobulin (organification products); coupled by TPO to T3/T4. Free MIT/DIT released in lysosomes are deiodinated (DEHAL1) and iodide recycled.', tags: ['thyroid', 'organification'], refs: ['kovacs12'] });
  add('h2o2', 'metabolite', 'H₂O₂', { tags: ['thyroid'] });
  add('tbg', 'protein', 'TBG / TTR / albumin', { short: 'Binding proteins', what: 'Plasma carriers of T4/T3 (TBG binds most T4). Only the free hormone enters cells and feeds back.', tags: ['thyroid', 'transport'], refs: ['kovacs12'] });
  add('pregnenolone', 'metabolite', 'Pregnenolone', { what: 'First steroid (C21, Δ5), from cholesterol via CYP11A1.', tags: ['steroidogenesis'] });
  add('prog_a', 'metabolite', 'Progesterone', { tags: ['steroidogenesis'] });
  add('doc', 'metabolite', '11-Deoxycorticosterone (DOC)', { short: 'DOC', what: 'Mineralocorticoid precursor with significant MR activity — accumulates in 11β-hydroxylase and 17α-hydroxylase deficiencies, causing hypertension.', tags: ['steroidogenesis', 'mineralocorticoid'], refs: ['miller2011'] });
  add('corticosterone', 'metabolite', 'Corticosterone', { tags: ['steroidogenesis'] });
  add('oh18b', 'metabolite', '18-OH-corticosterone', { tags: ['steroidogenesis'] });
  add('oh17preg', 'metabolite', '17-OH-pregnenolone', { tags: ['steroidogenesis'] });
  add('oh17p', 'metabolite', '17-OH-progesterone (17-OHP)', { short: '17-OHP', what: 'Substrate of 21-hydroxylase in the cortisol pathway. Markedly elevated in 21-hydroxylase deficiency (newborn screening marker).', tags: ['steroidogenesis', 'CAH'], refs: ['speiser2018'] });
  add('deoxycortisol', 'metabolite', '11-Deoxycortisol', { what: 'Cortisol precursor; elevated in 11β-hydroxylase deficiency and after metyrapone.', tags: ['steroidogenesis'] });
  add('dhea', 'metabolite', 'DHEA / DHEA-S', { short: 'DHEA(-S)', what: 'Weak adrenal androgen precursors from zona reticularis (CYP17 17,20-lyase). Converted peripherally to androstenedione, testosterone and estrogens.', tags: ['androgen', 'zona reticularis', 'adrenarche'], refs: ['miller2011'] });
  add('androstenedione', 'metabolite', 'Androstenedione', { tags: ['androgen', 'steroidogenesis'] });
  add('estrone', 'metabolite', 'Estrone', { tags: ['estrogen'] });
  add('cortisone', 'metabolite', 'Cortisone', { tags: ['cortisol'] });
  add('tyrosine', 'metabolite', 'Tyrosine', { tags: ['catecholamine', 'thyroid'] });
  add('ldopa', 'metabolite', 'L-DOPA', { tags: ['catecholamine'] });
  add('metaneph', 'metabolite', 'Metanephrines / VMA', { tags: ['catecholamine'] });
  add('angiotensinogen', 'metabolite', 'Angiotensinogen → Ang I', { short: 'Angiotensinogen', tags: ['RAAS'] });
  add('pomc', 'protein', 'POMC', { what: 'Pro-opiomelanocortin — precursor of ACTH, α-MSH, β-endorphin.', tags: ['HPA'] });
  add('cpeptide', 'metabolite', 'C-peptide', { what: 'Released equimolar with insulin; longer t½ (~35 min) and little hepatic extraction, so it indexes endogenous secretion (Molina Ch7).', clin: 'Low C-peptide with high insulin → exogenous insulin (factitious hypoglycemia).', tags: ['insulin', 'beta cell'], refs: ['molina7'] });
  add('phosphate', 'ion', 'Phosphate (PO₄)', { short: 'Phosphate', what: 'Mineral partner of calcium in hydroxyapatite and a key intracellular anion (ATP, 2,3-BPG). Regulated mainly by renal excretion (PTH, FGF23) and intestinal absorption (calcitriol).', tags: ['phosphate', 'bone', 'kidney', 'FGF23'], refs: ['kovacs14', 'blaine2015'] });
  add('hydroxyapatite', 'metabolite', 'Bone mineral (hydroxyapatite)', { short: 'Bone mineral', tags: ['bone'] });
  add('water', 'metabolite', 'Water', { tags: ['ADH'] });

  // ======================= PROCESSES =======================
  const P = (id, name, what, tags, refs) => add(id, 'process', name, { what, tags, refs });
  P('glycolysis', 'Glycolysis', 'Glucose → 2 pyruvate (+2 ATP, 2 NADH) in the cytosol. Liver glycolysis is hormonally regulated at glucokinase, PFK-1 (via F-2,6-BP) and L-pyruvate kinase; muscle glycolysis is driven mostly by energy demand (AMP, Ca²⁺).', ['glycolysis', 'glucose'], ['kovacs15', 'pilkis1992']);
  P('gluconeogenesis', 'Gluconeogenesis', 'Synthesis of glucose from lactate, glycerol, alanine/glutamine and other glucogenic amino acids (liver, and kidney in prolonged fasting). Bypasses the three irreversible glycolytic steps: pyruvate carboxylase + PEPCK, FBPase-1, G6Pase. Controlled by substrate supply, acetyl-CoA (PC), F-2,6-BP, and gene transcription (FOXO1, CREB/CRTC2, PGC-1α, GR).', ['gluconeogenesis', 'fasting', 'liver', 'acetyl-CoA'], ['kovacs15', 'pilkis1992', 'petersen2018']);
  P('glycogenesis', 'Glycogenesis', 'Glycogen synthesis (G6P → G1P → UDP-glucose → glycogen) — activated by insulin (GSK3 inhibition, PP1) and by glucose/G6P allosterically.', ['glycogen'], ['petersen2018']);
  P('glycogenolysis', 'Glycogenolysis', 'Glycogen breakdown by glycogen phosphorylase. Liver: glucagon (and epinephrine) via PKA → phosphorylase kinase, exporting glucose. Muscle: epinephrine (β2) and contraction (Ca²⁺, AMP) — used locally.', ['glycogen', 'glucagon', 'exercise'], ['molina7', 'ramnanan2011']);
  P('lipogenesis', 'De novo lipogenesis', 'Synthesis of fatty acids from acetyl-CoA (citrate export → ACC → malonyl-CoA → FAS), esterified to triglyceride. Mainly hepatic in humans; driven by insulin (SREBP-1c) and carbohydrate (ChREBP).', ['lipogenesis', 'fatty acid synthesis', 'malonyl-CoA'], ['kovacs15', 'rui2014']);
  P('lipolysis', 'Lipolysis', 'Hydrolysis of stored triglyceride to fatty acids + glycerol (ATGL → HSL → MGL). Exquisitely sensitive to insulin suppression; stimulated by catecholamines, permissively by GH and cortisol.', ['lipolysis', 'adipose', 'fasting'], ['zechner2012']);
  P('betaox', 'β-Oxidation', 'Mitochondrial fatty acid oxidation (after CPT-1 gating) producing acetyl-CoA, NADH and FADH₂.', ['fatty acid oxidation', 'acetyl-CoA', 'CPT-1'], ['mcgarry1980']);
  P('ketogenesis', 'Ketogenesis', 'Hepatic mitochondrial synthesis of acetoacetate and β-hydroxybutyrate from acetyl-CoA via HMGCS2. Requires high fatty acid delivery, an open CPT-1 (low malonyl-CoA), and low insulin.', ['ketogenesis', 'fasting', 'acetyl-CoA', 'glucagon'], ['mcgarry1980', 'puchalska2017', 'kovacs15']);
  P('ketolysis', 'Ketolysis (ketone oxidation)', 'Extrahepatic oxidation: β-HB → acetoacetate → (SCOT) acetoacetyl-CoA → 2 acetyl-CoA → TCA. Brain uptake rises with blood concentration and MCT expression during prolonged fasting.', ['ketolysis', 'brain', 'fasting'], ['puchalska2017', 'owen1967']);
  P('ppp', 'Pentose phosphate pathway', 'G6P → (G6PD) → NADPH + ribose-5-P. Active in liver, adipose, adrenal and lactating mammary gland (lipogenic/steroidogenic tissues need NADPH) and red cells (glutathione).', ['pentose phosphate', 'NADPH'], ['kovacs15']);
  P('ureacycle', 'Urea cycle', 'Hepatic pathway converting NH₄⁺ (+ aspartate nitrogen) to urea. Flux follows nitrogen load; glucagon and glucocorticoids increase capacity.', ['urea cycle', 'nitrogen', 'amino acid'], ['albrechtsen2019']);
  P('protsyn', 'Protein synthesis', 'mTORC1-driven translation (S6K1, 4E-BP1). Stimulated by insulin and amino acids (leucine), IGF-1, exercise; opposed by cortisol and energy stress (AMPK).', ['protein synthesis', 'mTOR'], ['saxton2017']);
  P('proteolysis', 'Proteolysis', 'Muscle protein breakdown (ubiquitin–proteasome, autophagy) releasing amino acids, especially alanine and glutamine. ↑ cortisol, ↓ insulin; falls in prolonged starvation as ketones replace glucose (protein sparing).', ['proteolysis', 'muscle', 'fasting', 'cortisol'], ['cahill2006', 'felig1973']);
  P('tgsynth', 'Triglyceride synthesis (esterification)', 'Glycerol-3-P + 3 acyl-CoA → triglyceride (adipose, liver).', ['triglyceride', 'storage'], ['kovacs15']);
  P('transamination', 'Transamination', 'Transfer of α-amino groups to α-ketoglutarate (→ glutamate) leaving carbon skeletons.', ['amino acid', 'nitrogen'], ['felig1973']);
  P('deamination', 'Oxidative deamination', 'Glutamate → α-KG + NH₄⁺ (GDH) in liver mitochondria.', ['nitrogen'], []);
  P('chol_synth', 'Cholesterol synthesis', 'Cytosolic acetyl-CoA → HMG-CoA → (HMG-CoA reductase) mevalonate → squalene → cholesterol.', ['cholesterol'], ['kovacs15']);
  P('glucose_uptake', 'Glucose uptake', 'Transport of glucose into cells.', ['glucose', 'GLUT4'], []);
  P('exocytosis', 'Exocytosis', 'Ca²⁺-triggered fusion of secretory granules/vesicles with the plasma membrane.', ['secretion'], []);
  P('steroidogenesis', 'Steroidogenesis', 'Synthesis of steroid hormones from cholesterol.', ['steroidogenesis'], ['miller2011']);
  P('transcription', 'Gene transcription', 'Nuclear receptor or transcription-factor–driven change in mRNA synthesis — slow (hours) but sustained.', ['transcription', 'nuclear receptor'], ['kovacs3']);
  P('spermatogenesis', 'Spermatogenesis', 'Requires FSH (Sertoli) and very high intratesticular testosterone (LH → Leydig).', ['HPG', 'Sertoli'], ['kovacs9']);
  P('boneresorp', 'Bone resorption', 'Osteoclast-mediated dissolution of mineral (H⁺ via V-ATPase) and matrix (cathepsin K), releasing Ca²⁺ and phosphate.', ['bone', 'calcium'], ['boyle2003', 'kovacs14']);
  P('boneform', 'Bone formation', 'Osteoblast matrix (osteoid) deposition and mineralization.', ['bone'], ['kovacs14']);
  P('osteoclastogenesis', 'Osteoclastogenesis', 'RANKL + M-CSF drive fusion of monocyte/macrophage precursors into multinucleated osteoclasts.', ['bone'], ['boyle2003']);

  // ======================= ORGANS & CELLS =======================
  const O = (id, type, name, what, tags) => add(id, type, name, { what, tags });
  O('liver', 'organ', 'Liver', 'The metabolic switchboard: buffers blood glucose (glycogen, gluconeogenesis), makes ketones, VLDL, urea, IGF-1, binding proteins; first-pass clearance of portal insulin and glucagon.', ['liver']);
  O('muscle', 'organ', 'Skeletal muscle', 'Largest site of insulin-stimulated glucose disposal (mostly into glycogen — Shulman 1990); protein reservoir (alanine/glutamine) during fasting; lacks G6Pase and functional glucagon signaling.', ['muscle']);
  O('adipose', 'organ', 'Adipose tissue', 'Triglyceride store; releases FFA + glycerol; secretes leptin and adiponectin; site of aromatase.', ['adipose']);
  O('brain', 'organ', 'Brain', 'Obligate glucose user (insulin-independent GLUT1/3) that can switch to ketones in prolonged fasting; integrates feeding, stress and reproductive signals in the hypothalamus.', ['brain']);
  O('pancreas', 'organ', 'Pancreatic islets', 'α (glucagon), β (insulin), δ (somatostatin) cells sensing glucose, amino acids, incretins and autonomic input; intra-islet paracrine signaling.', ['pancreas', 'islet']);
  O('kidney', 'organ', 'Kidney', 'Gluconeogenesis (important in prolonged fasting/acidosis), glucose reabsorption (SGLT2), 1α-hydroxylation of vitamin D, Ca/phosphate/water/Na handling, renin.', ['kidney']);
  O('gut', 'organ', 'Intestine', 'Absorbs nutrients; enteroendocrine L- and K-cells secrete GLP-1 and GIP (feed-forward to islets).', ['gut', 'incretin']);
  O('hypothalamus', 'organ', 'Hypothalamus', 'Neuroendocrine command centre: releasing/inhibiting hormones into the portal circulation; magnocellular ADH/oxytocin neurons; integrates feedback.', ['hypothalamus']);
  O('pituitary', 'organ', 'Anterior pituitary', 'Somatotrophs, lactotrophs, corticotrophs, thyrotrophs, gonadotrophs; receives hypothalamic signals through the hypophyseal portal veins.', ['pituitary']);
  O('postpit', 'organ', 'Posterior pituitary', 'Axon terminals of hypothalamic magnocellular neurons storing ADH and oxytocin.', ['pituitary']);
  O('thyroid', 'organ', 'Thyroid', 'Follicles of thyrocytes surrounding colloid (thyroglobulin store); parafollicular C-cells (calcitonin).', ['thyroid']);
  O('adrenal', 'organ', 'Adrenal cortex', 'Zona glomerulosa (aldosterone), fasciculata (cortisol), reticularis (DHEA/androgens).', ['adrenal']);
  O('medulla', 'organ', 'Adrenal medulla', 'Chromaffin cells (modified postganglionic sympathetic neurons) secreting mainly epinephrine.', ['adrenal medulla']);
  O('bone', 'organ', 'Bone', 'Calcium and phosphate reservoir; osteoblasts, osteocytes (FGF23, sclerostin), osteoclasts.', ['bone']);
  O('parathyroid', 'organ', 'Parathyroid glands', 'Chief cells sense Ca²⁺ via CaSR and secrete PTH.', ['calcium']);
  O('testis', 'organ', 'Testis', 'Leydig cells (testosterone, LH-driven) and Sertoli cells (FSH-driven: spermatogenesis support, inhibin B, ABP, AMH).', ['HPG']);
  O('ovary', 'organ', 'Ovary', 'Theca (LH → androgens) and granulosa (FSH → aromatase → estradiol; inhibin) cells; corpus luteum (progesterone).', ['HPG']);
  O('immune', 'organ', 'Immune system', 'Glucocorticoids suppress cytokine production (NF-κB/AP-1 tethering), eosinophils/lymphocytes, and inflammation.', ['cortisol']);
  O('heart', 'organ', 'Heart', 'Omnivorous oxidative organ (FFA, lactate, ketones, glucose); thyroid hormone and catecholamines increase contractility/rate.', ['heart']);
  O('placenta', 'organ', 'Placenta', 'Makes hCG, hPL, progesterone, and estrogens (aromatizing fetal adrenal DHEA-S).', ['pregnancy']);
  O('rbc', 'organ', 'Red blood cells', 'Glycolytic only (no mitochondria): obligate glucose users producing lactate.', ['glucose']);
  O('leydig', 'cell', 'Leydig cell', 'Interstitial testicular cell: LH → cAMP → StAR → testosterone.', ['HPG']);
  O('sertoli', 'cell', 'Sertoli cell', 'Seminiferous-tubule "nurse" cell: FSH → ABP, inhibin B, aromatase; tight junctions form the blood–testis barrier.', ['HPG']);
  O('theca', 'cell', 'Theca cell', 'Ovarian follicle cell with LH receptors and CYP17: makes androstenedione.', ['HPG']);
  O('granulosa', 'cell', 'Granulosa cell', 'Follicle cell with FSH receptors and aromatase: converts theca androgens to estradiol (two-cell, two-gonadotropin model).', ['HPG']);
  O('osteoblast', 'cell', 'Osteoblast / osteocyte', 'Bone-forming lineage; expresses PTH1R, VDR; produces RANKL, OPG, FGF23, sclerostin.', ['bone']);
  O('osteoclast', 'cell', 'Osteoclast', 'Multinucleated bone-resorbing cell.', ['bone']);
  O('betacell', 'cell', 'β-cell', 'Insulin-secreting islet cell.', ['beta cell']);
  O('alphacell', 'cell', 'α-cell', 'Glucagon-secreting islet cell.', ['alpha cell']);
  O('gonadotroph', 'cell', 'Gonadotroph', 'Pituitary LH/FSH cell.', ['HPG']);
  O('lactotroph', 'cell', 'Lactotroph', 'Pituitary prolactin cell.', ['prolactin']);
  O('corticotroph', 'cell', 'Corticotroph', 'Pituitary ACTH cell.', ['HPA']);
  O('thyrotroph', 'cell', 'Thyrotroph', 'Pituitary TSH cell.', ['HPT']);
  O('somatotroph', 'cell', 'Somatotroph', 'Pituitary GH cell.', ['GH axis']);
  O('chromaffin', 'cell', 'Chromaffin cell', 'Adrenal medullary catecholamine cell.', ['catecholamine']);
  O('enterocyte', 'cell', 'Enterocyte', 'Intestinal absorptive cell.', ['gut']);

  // ======================= DRUGS (Level 4) =======================
  const D = (id, name, what, tags) => add(id, 'drug', name, { what, tags });
  D('sulfonylurea', 'Sulfonylureas', 'Close β-cell K-ATP channels (bind SUR1) → depolarization → insulin release regardless of glucose → hypoglycemia risk.', ['beta cell', 'diabetes']);
  D('glp1ra', 'GLP-1 receptor agonists', 'Long-acting GLP-1R agonists (e.g., semaglutide): glucose-dependent insulin release, ↓ glucagon, slowed gastric emptying, weight loss.', ['incretin', 'diabetes']);
  D('metformin', 'Metformin', 'Lowers hepatic glucose production; proposed mechanisms include altered hepatic redox/energy state and AMPK activation (mechanism still debated). Does not cause hypoglycemia alone.', ['diabetes', 'AMPK']);
  D('methimazole', 'Thionamides (methimazole, PTU)', 'Inhibit TPO (organification and coupling); PTU also inhibits peripheral D1.', ['thyroid']);
  D('levothyroxine', 'Levothyroxine', 'Synthetic T4 replacement; converted to T3 by deiodinases.', ['thyroid']);
  D('dexamethasone', 'Exogenous glucocorticoid', 'Activates GR → suppresses CRH/ACTH → adrenal atrophy with chronic use (risk of adrenal crisis on abrupt withdrawal).', ['HPA']);
  D('cabergoline', 'Dopamine agonists', 'D2 agonists (cabergoline, bromocriptine) suppress prolactin and shrink prolactinomas.', ['prolactin']);
  D('finasteride', 'Finasteride', '5α-reductase inhibitor.', ['androgen']);
  D('aromataseinh', 'Aromatase inhibitors', 'Letrozole/anastrozole block estrogen synthesis.', ['estrogen']);
  D('denosumab', 'Denosumab', 'Anti-RANKL antibody → inhibits osteoclastogenesis.', ['bone']);
  D('cinacalcet', 'Cinacalcet', 'CaSR positive allosteric modulator → ↓ PTH.', ['calcium']);
  D('statin', 'Statins', 'HMG-CoA reductase inhibitors → ↓ hepatic cholesterol → ↑ LDL receptors → ↓ LDL.', ['cholesterol']);
  D('perchlorate', 'Perchlorate', 'Competitive NIS inhibitor.', ['thyroid']);
  D('gnrhag', 'Continuous GnRH agonist', 'Initial flare then receptor desensitization and suppression of LH/FSH (medical castration).', ['HPG']);
  D('sglt2i', 'SGLT2 inhibitors', 'Block renal glucose reabsorption (glycosuria); lower insulin and raise glucagon modestly → can promote ketogenesis.', ['diabetes', 'kidney']);
  D('insulin_rx', 'Exogenous insulin', 'Subcutaneous insulin enters the systemic (not portal) circulation — the liver sees relatively less insulin than with endogenous secretion.', ['diabetes']);
})();
